INSERT INTO public.training_library (age_group, training_number, exercises)
VALUES
('O12', 1, '{"session_a": [{"type": "warming_up", "title": "DRIBBELTIKKERTJE", "content": "Alle spelers, behalve de tikker, dribbelen met de bal aan de voet in het speelveld.\nDe tikker heeft zijn bal in de handen en moet nu met zijn bal proberen de bal van\neen dribbelende speler te tikken.\nAls dit is lukt, wordt de afgetikte speler de nieuwe tikker, etc.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 6-12 spelers\nPylonen: 4 om het speelveld af te bakenen.\nAantal ballen: zoveel als nodig is voor het spel."}, {"type": "techniek", "title": "STAP 2.5 C: AANNEMEN-OPENEN, TOT 90º IN PLUSVORM (2)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal met de binnenkant van de rechtervoet\naan.\nC. Speler 1 speelt naar speler 3\n- Idem als beschreven bij A, etc.\nD. Speler 3 dribbelt met de bal om de pylon naar speler 8\n- Speler 3 sluit achter speler 8 aan.\nE. Speler 4 start oefening opnieuw.\nF. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\n- Idem, met links aannemen en met links spelen.\n- Idem, maar nu in tegengestelde richting uitvoeren.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 2\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "(5 : 3) OEFENING 3", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdedigers moeten na het veroveren van de bal op de kleine\ndoeltjes scoren (omschakeling).\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nKleine doelen: 2x (3m bij 1m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- hetzodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 3:3", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 6\nAantal ballen: veel\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2 mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering."}], "session_b": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen\nSPRINTTEST\nMethodiek\nVoor deze test wordt in de breedte van het strafschopgebied, op\neen onderlinge afstand van tekens 10 meter, met 5 pylonen een\nparcours uitgezet.\nDe spelers starten de sprint vanaf de zijkant van het “16-\nmetergebied” vanuit stilstand en sprinten vervolgens om de\neerste pylon heen weer terug, gevolgd door een sprint om de\ntweede pylon heen en weer terug. Idem om de derde en de vierde\npylon.\nDe behaalde eindtijd wordt gemeten en vastgelegd.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen: 5\nAfstand tussen de pylonen: 10 mtr.\n1 stopwatch\nSchrijfbenodigdheden.\n- deze test heeft tot doel om de “reactie/\nacceleratie- en/of de maximale snelheid” te\ntoetsen/meten.\nAanwijzingen\n- zowel heen als terug een zo hoog mogelijke\nsnelheid ontwikkelen\n- kort om de pylon draaien\n- neem minimaal 2-3 minuten rust tussen\ntwee testen."}, {"type": "techniek", "title": "OPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (6+KEEPER : 5)", "content": "D.w.z. dat 6 verdedigers/ middenvelders+ keeper d.m.v.\nsamenspel 5 aanvallers/ middenvelders uitspelen, om daarna de\nbal over de lijn van één van de doeltjes te dribbelen.\nBal afgepakt dan kunnen de aanvallers op het grote doel scoren.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 11+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 30m bij 35m\nD-pupillen: 35m bij 40m\nC-,B-,A-junioren: 40m bij 45m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen van de centrale\nmiddenvelder en het in de bal komen van de\nandere middenvelder (6+8)\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O12', 2, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER ACHTER JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen buitenkant voet (Stap 3)\n- Binnen-buitenkant wegdraai (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.7 A: AANNEMEN (MET HOOFD) EN SPELEN (HEEN TERUG)\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op hoofdhoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 1\n- Speler 2 neemt de bal met het voorhoofd aan en speelt de bal\nbinnenkant van de rechtervoet terug, etc.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 4 m\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAannemen:\n- Bij het aannemen met het hoofd soepel en\nflexibel met de bal meegaan en zodoende bal\n\"dood\" maken.\n- Bal moet voor je liggen, maar binnen bereik\n- Snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "3. (6 : 3)", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 3\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 9\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "HOEK VOETBAL 7 TEGEN 7", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen op een groot vierkant veld, waarvan de\nhoeken gemarkeerd zijn met pylonen.\nIn de hoeken van het veld kan de partij in balbezit scoren. Alleen\nde balbezittende partij mag in deze hoeken komen.\nAls je gescoord hebt behoud je team balbezit en mag je proberen\nin één van de andere hoeken te scoren.\nLET OP:\nEr mag nooit 2x achter elkaar in dezelfde hoek gescoord worden\n(door beide teams niet).\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "KRUIS- EN AANSLUITPAS OVER EEN LIJN", "content": "Is een oefening, waarbij de speler(s)de stappen van de\nonderstaande technieken, in zijwaartse richting, over een\nrechtlopende lijn uitvoeren.\nDe speler(s) moet(en) hierbij beide bewegingsvormen uit kunnen\nvoeren.\n1. Aansluitpas (Stap 1,2,3)\n2. Kruispas (Stap 1,2,3)\nOpgelet!\nDit is een aanleervorm. Met deze oefening leer je de speler(s) de\nbewegingsvormen van de stappen 1 t/m 3 van beide passen aan.\nMaterialen\nAantal spelers: gehele team.\nOrganisatie:\nDeze oefeningen kunnen op elke lijn van het\nvoetbalveld worden uitgevoerd (bijv. zijkant van\nhet 16-metergebied).\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst"}, {"type": "techniek", "title": "A. EEN-TWEE OF TECHNIEK; BUITENKANT VOET, VOOR JE (1)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de buitenkant van de voet.\nUit te voeren technieken:\n- Akka (buitenkant-binnen) (Stap 4)\n- Schaar (Stap 6)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de buitenkant van de\nrechtervoet richting speler 1\nE. Speler 2 (doet alsof hij een 1 : 2 wil aangaan met speler 3)\nvoert daar één van onderstaande bewegingen uit:\n- Akka (buitenkant-binnen) (Stap 4)\n- Schaar (Stap 6)\nF. Speler 2 versnelt kort met de bal aan de buitenkant linkervoet\ntot aan de buitenste pylonen\nG. Speler 2 dribbelt rustig terug naar het beginpunt.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 6) en\nAkka (buiten-binnen) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan er start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "OEFENING 1", "content": "De spelers staan hierbij in twee rijen opgesteld.\nA. Speler 1 speelt de bal met de binnenkant van de rechtervoet op\nde van buiten naar binnen aanbiedende speler 2.\nB. Speler 2 neemt de bal in de loop mee en werkt hem af op het\ndoel.\nOpgelet!\nDe volgende speler start pas nadat er op doel geschoten is.\nDe spelers moeten de bal in één keer schieten en vooral niet stil\ngaan staan om te schieten.\nVariatie in uitvoering:\nNadat je geschoten hebt, wisselen van rij; wisselen van rij is\nwisselen van speelbeen.\nMaterialen\nAantal spelers: 8 - 12\nAantal ballen: voldoende\nDoel: 1 (7.32m bij 2.44m)\nAantal pylonen: 4\nFictieve buitenspellijn: 1\nDoordraaien:\n- De speler die op doel schiet haalt de bal en\nsluit weer achter in de rij aan.\n- Idem voor de andere rij.\nAanwijzingen\n- Het aanspelen van de bal met de juiste\nsnelheid en op het juiste moment\n- Het rustig beginnen en het langzaam\nopvoeren van de handelingssnelheid\n- Het uiteindelijk komen tot 1 x raken en\nafronden op het doel\nPARTIJVORM 7:7\nMethodiek\nZeven aanvallers moeten d.m.v. samenspel/ individuele actie 7\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij\nopnieuw.opnieuw.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nE-pupillen: 35m bij 40m\nD-pupillen: 40m bij 45m\nC-junioren: 45m bij 50m\nB-,A-junioren: 50m bij 55m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een 3-1-3 formatie.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering."}]}'::jsonb),
('O12', 3, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Pirouette (Stap 5)\n- Aai achter standbeen (Stap 4)\n- De Schijntrap (Stap 4)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.6 C: KAATSEN-OPENEN, TOT 90º IN PLUSVORM (2)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 3\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD. Speler 3 dribbelt met de bal om de pylon naar speler 8\n- Speler 3 sluit achter speler 8 aan.\nE. Speler 4 start oefening opnieuw.\nF. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\nIdem, maar nu in tegengestelde richting uitvoeren en met links\nuitvoeren.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 2\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "2. (4 : 2 + 2)", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de 2 verdedigers de bal kunnen veroveren.\nWanneer de verdedigers de bal onderscheppen dan moeten zij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 2 verdedigers en 2 aanvallers mee naar het andere\nveld. Nu moeten de vier verdedigers d.m.v, samenspel de bal in\nhun bezit zien te houden zonder dat de 2 aanvallers de bal\nkunnen veroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (12m bij 10m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)\nPARTIJVORM 3:3\nMethodiek\nDrie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 6\nAantal ballen: veel\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2 mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering."}], "session_b": [{"type": "warming_up", "title": "OMSCHAKELING MET BAL (2)", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nBij dit spel brengen de spelers van de ene groep de bal buiten de middencirkel\n(niet schieten). De andere spelers van elk tweetal uit de andere groep pakken de\nbal weer op en brengen deze weer naar de middencirkel.\nWelk tweetal heeft als eerste 5 ballen bij elkaar?\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- middencirkel."}, {"type": "techniek", "title": "STAP 2.3 C: INGOOIEN, AANNEMEN-OPENEN, TOT 90º IN PLUSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"voorwaarts\" aan\n- speler 1 gooit de bal in\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich \"naar rechts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 1 neemt de bal met de binnenkant van de rechtervoet aan.\nC. Speler 1 speelt naar speler 3\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD.Speler 3 dribbelt met de bal om de pylon naar speler 8\n- speler 3 sluit achter speler 8 aan.\nE. Speler 4 start oefening opnieuw.\nF. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\n- Idem, met links aannemen en met links spelen\n- idem, maar nu in tegengestelde richting uitvoeren.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 2\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- na het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nIngooi:\n- beide voeten houden contact met de grond\n- de bal achter het hoofd loslaten\n- beide handen op de bal houden\n- voeten in de richting van het gooien\n- op het juiste been ingooien.\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2.5 A: KOPPEN (RECHT) VANUIT EEN VOORWAARTSE BEWEGING", "content": "A. Speler 2 speelt naar speler 1\n- Vanuit het midden gooit speler 2 de bal onderhands recht aan\nnaar de inlopende speler 1 (op 2-3 meter afstand).\nB. Speler 1 speelt naar speler 2\n- Speler 1 kopt de bal met een één/ tweebenige afzet recht terug\nin de handen van speler 2.\nC. Speler 2 speelt naar speler 3\n- Idem als A naar speler 3.\nOpgelet!\n- Idem voor de spelers 4,5 en 6 in tegenovergestelde richting.\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 3-4\nAantal pylonen: 3\nOnderlinge afstand pylonen: 4m\nDoordraaien:\nB1. Achter de bal aan doorlopen naar de�positie\naan de andere kant.\nWisselen van functie naar eigen inzicht.\nAanwijzingen\n- Vroegtijdig afzetten.\n- Afzetbeen terugbrengen in spanboog.\n- Zwaaibeen blijft gebogen voor-hoog.\n- Bal moet op het hoogste punt van de\nsprong worden gekopt (dode punt).\n- Juiste moment bovenlichaam naar voren en\narmen naar achter.\n- Bal raken met het voorhoofd.\n- De bal goed richting geven, door de\nduwbeweging in de richting van speler 2 te\nmaken.\nLIJNDRIBBEL 4:3 MET DOEL\nMethodiek\nd.w.z. dat 4 aanvallers d.m.v. samenspel/ een persoonlijke actie 3\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 4 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger (alleen van\ntoepassing voor teams 11-11).\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nD-pupillen: 30m bij 25m\nC-,B-,A-junioren: 35m bij 30m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gezorgd moet worden dat de\nnummer 3 de vrije man is\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers\nVerdedigers coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O12', 4, '{"session_a": [{"type": "warming_up", "title": "DRIE IS TEVEEL", "content": "De spelers vormen naast elkaar staande tweetallen verspreid over\nhet hele vak. Twee spelers, 1 loper en 1 tikker vormen geen\ntweetal. De loper probeert de tikker te ontlopen en kan zich\ndaarbij vrijspelen door naast een tweetal te gaan staan.\nDe speler die aan de andere buitenkant komt te staan wordt\ndaardoor de nieuwe loper, die getikt moet worden.\nOpgelet!\nEen getikte speler wordt direct de nieuwe tikker.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 12 of meer spelers\nPylonen: 4 om het speelveld af te bakenen.\nAanwijzingen\n- De spelers moeten stil op hun plek blijven\nstaan"}, {"type": "techniek", "title": "B. EEN-TWEE OF TECHNIEK; BINNENKANT VOET, VOOR JE (1)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de binnenkant van de voet.\nUit te voeren technieken:\n- Aai buitenkant voet (Stap 6)\n- Sleep (Stap 5)\n- Akka (binnen-voor) (Stap 4)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de binnenkant van de\nrechtervoet richting speler 1\nE. Speler 2 (doet alsof hij een 1 : 2 wil aangaan met speler 3)\nvoert daar één van onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 6)\n- Sleep (Stap 5)\n- Akka (binnen-voor) (Stap 4)\nF. Speler 2 versnelt kort met de bal aan buitenkant linkervoet tot\naan de buitenste pylonen\nG. Speler 2 dribbelt rustig terug naar het beginpunt.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 6), Sleep (Stap 5) en Akka (binnen-voor) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 2\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan er start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "3. (6 : 3)", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 3\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 9\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "RUIMTE VOETBAL 7 TEGEN 7", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen op een groot veld (ca. half voetbalveld).\nBeide teams verdedigen één kant van het veld, met daarop 2\ngrote poorten (min. 8 m. breed), die ca. 8 m. vanaf de achterlijn\nstaan.\nHet team in balbezit kan scoren door, zonder tussenkomst van de\ntegenstander, de bal naar elkaar over te spelen en daarna te\nscoren in één van de 2 poorten aan de lange zijde van de\ntegenstander..\nOpgelet:\n- men houdt balbezit na het score\n- er kan van beide kanten door de poorten worden gescoord.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "TRIPLING MET BAL", "content": "Is een oefening, waarbij de speler de stap van de onderstaande\ntechniek uitvoert, terwijl hij zich voorwaarts beweegt. De speler\nraakt, bij elke voetplaatsing van de tripling, de bal met de punt\nvan de schoen en volgt zo de baan van de bal.\n1. Tripling (Stap 4)\nOpgelet!\nDit is een eindvorm, die alleen kan worden uitgevoerd als de\nspeler de laatste stap van de tripling voldoende beheerst.\nDifferentiatie:\nUitvoering in parcoursvorm, waarbij constant van richting moet\nworden veranderd.\nMaterialen\nAantal spelers: gehele team\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\nDe spelers lopen van achterlijn tot 16-meterlijn\nin het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.8 A: KAATSEN HOOG (MET BINNENKANT VOET), HEEN TERUG\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 1\n- Speler 2 kaatst de bal direct met de binnenkant van de\nrechtervoet terug in de handen van speler 1, etc.\nVariatie in uitvoering:\nIdem, met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid/richting terug\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "OEFENING 2", "content": "De spelers staan hierbij in twee rijen opgesteld.\nA. Speler 1 speelt de bal met de binnenkant van de rechtervoet op\nde naar buiten aanbiedende speler 2 en loopt daarna door in de\nrichting van het doel.\nB. Speler 2 speelt de bal terug in de loop van speler 1.\nC. Speler 1 neemt de bal in de loop mee en werkt daarna af op het\ndoel.\nOpgelet!\nDe volgende speler start pas nadat er op doel geschoten is.\nDe spelers moeten de bal in één keer schieten en vooral niet stil\ngaan staan om te schieten.\nVariatie in uitvoering:\nNadat je geschoten hebt, wisselen van rij; wisselen van rij is\nwisselen van speelbeen.\nMaterialen\nAantal spelers: 8 - 12\nAantal ballen: voldoende\nDoel: 1 (7.32m bij 2.44m)\nAantal pylonen: 4\nFictieve buitenspellijn: 1\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2.\n- Speler 2 haalt de bal en sluit achter in de rij\nvan speler 1 aan.\n- Idem voor de andere rij.\nAanwijzingen\n- Het aanspelen van de bal met de juiste\nsnelheid en op het juiste moment\n- Het rustig beginnen en het langzaam\nopvoeren van de handelingssnelheid\n- Het uiteindelijk komen tot 1 x raken en\nafronden op het doel\nNIET IN HET WATER 7 TEGEN 7\nMethodiek\nDeze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen.\nIn het veld staan 2 doelen met de achterkanten naar elkaar toe.\nTussen de doelen is een vak (water), waar geen spelers mogen\nkomen. De bal mg wel door het vak gespeeld worden.\nHet team dat scoort in het doel van de tegenstander krijgt 1 punt.\nOpgelet:\n- als een speler door het water loopt, krijgt de tegenstander een\nvrije bal op de achterlijn, aan de kant van het doel waar zij\nmoeten scoren.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 8\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O12', 5, '{"session_a": [{"type": "warming_up", "title": "LIJNEN SPEL", "content": "De spelers staan met de bal aan de voet op een door de trainer\naangegeven lijn van het 16- meter gebied. Op zijn teken dribbelen\nde spelers naar een door de trainer aangegeven andere lijn.\nOpgelet!\nGeen 16- meter gebied beschikbaar, maak dan gebruik van\nverschillend gekleurde pylonen of hoedjes om daarmee lijnen te\nvormen\nMaak bij de\" jongste jeugd\" gebruik van nummers.\nVariatie:\n- Geef elke speler bij aanvang 3 punten en haal bij de laatste\ntelkens 1 punt af. Winnaar is ook nu weer degene die over blijft.\n- Laatste valt steeds af en winnaar is degene die over blijft (alleen\ndoen als afsluiting van een training).\nMaterialen\nAantal spelers: 4-14\nAantal pylonen: 10 (om eventueel de lijnen aan\nte geven)\nAantal ballen: elke speler 1 bal\nAanwijzingen\nSpelers coachen op:\n- Draai eerst proef.\n- De bal moet wel steeds op de lijn onder de\nvoet stil liggen."}, {"type": "techniek", "title": "STAP 2.5 C: AANNEMEN-OPENEN, TOT 90º IN PLUSVORM (3)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1\n- Idem als beschreven bij A, etc.\nC. Speler 1 speelt naar speler 3\n- Idem als beschreven bij A, etc.\nD. Speler 3 speelt naar speler 2\n- Idem als beschreven bij A, etc.\nE. Speler 2 speelt naar speler 3\n- Idem als beschreven bij A, etc.\nF. Speler 3 dribbelt met de bal om de pylon naar speler 4\n- Speler 3 sluit achter speler 4 aan.\nG. Speler 4 start oefening opnieuw\nH. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\n- Idem, met links aannemen en met links spelen.\n- Idem, maar nu in tegengestelde richting uitvoeren.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 2\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "2. (4 : 2 + 2)", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de 2 verdedigers de bal kunnen veroveren.\nWanneer de verdedigers de bal onderscheppen dan moeten zij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 2 verdedigers en 2 aanvallers mee naar het andere\nveld. Nu moeten de vier verdedigers d.m.v, samenspel de bal in\nhun bezit zien te houden zonder dat de 2 aanvallers de bal\nkunnen veroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (12m bij 10m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "BELGISCH VOETBAL 6 TEGEN 6 + 2 KEEPERS", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 6 spelers en 1\nkeeper, die tegen elkaar spelen.\nElk team verdedigt één doel. De doelen staan in het midden van\nhet veld met de achterkanten tegen elkaar.\nAls je scoort in het doel van de tegenstander krijg je een punt.\nVariatie:\n- als een team een goede hoge bal kan spelen, evt.toevoegen dat\nde bal niet hoog gepeeld mag worden, of omgekeerd als ze het\nniet kunnen.\nMaterialen\nAantal spelers: 12 + 2 Keepers\nAantal ballen: 5\nAantal pylonen: 4\nDoel: 2\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "REACTIE-ACTIE", "content": "Dit is een oefening voor het hele team. Het hele team zit/ ligt hierbij op de\nachterlijn van het 16-metergebied. Op een teken van de trainer (b.v. “JA”) staan\nde spelers op en versnellen naar de overkant.\nDifferentiatie:\n- varieer in de uitgangshouding, zoals zitten op de billen, liggen op de buik, -\nzijde (beide kanten) of op de rug.\nWees daarbij creatief!\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: gehele team.\nOrganisatie:\nAchterlijn 16-meter gebied."}, {"type": "techniek", "title": "C. EEN-TWEE OF TECHNIEK; BINNENKANT ANDERE VOET, VOOR JE (1)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de binnenkant van de andere voet.\nUit te voeren technieken:\n- Uitstappen meenemen (Stap 6)\n- Akka (binnen-buiten) (Stap 4)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de binnenkant van de\nlinkervoet richting speler 1\nE. Speler 2 (doet alsof hij een 1 : 2 wil aangaan met speler 3)\nvoert daar één van onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 6)\n- Akka (binnen-buiten) (Stap 4)\nF. Speler 2 versnelt kort met de bal aan buitenkant linkervoet tot\naan de buitenste pylonen\nG. Speler 2 dribbelt rustig terug naar het beginpunt.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 6) en Akka (binnen-buiten) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 2\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan er start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (6 : 5+KEEPER)", "content": "D.w.z. dat de 6 aanvallers/ middenvelder d.m.v. samenwerken\nkansen creëren.\nDe 5 verdedigers /middenvelders+ keeper kunnen hierbij scoren\ndoor de bal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 11+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 30m bij 35m\nD-pupillen: 35m bij 40m\nC-,B-,A-junioren: 40m bij 45m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O12', 6, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM HEEN TERUG", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt naar overstaande pylon.\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Kappen achter standbeen (Stap 2)\n- Kappen binnenkant voet (Stap 3)\n- Kappen buitenkant voet (Stap 3)\n- De Overstap (Stap 4)\nC. Speler dribbelt terug en herhaald stap B bij de pylon.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: IN LIJNVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- De verandering (Stap 3)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.8 A: KAATSEN HOOG (MET BINNENKANT VOET), HEEN TERUG\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 1\n- Speler 2 kaatst de bal direct met de binnenkant van de\nrechtervoet terug in de handen van speler 1, etc.\nVariatie in uitvoering:\nIdem, met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 2\nAantal pylonen: 2\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid/richting terug\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(5 : 3) OEFENING 3", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit\nhouden zonder dat de verdedigers de bal kunnen veroveren.\nDe verdedigers moeten na het veroveren van de bal op de kleine\ndoeltjes scoren (omschakeling).\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nKleine doelen: 2x (3m bij 1m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- hetzodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "KANTELEN VOETBAL 7 TEGEN 7", "content": "Deze oefening wordt uitgevoerd met 2 teams van elk 7 spelers,\nwaarbij van elk team 1 speler in één van de 2 vierkanten staat.\nHet team in balbezit kan scoren door hun speler in het vierkant\naan te spelen, die vervolgens de bal doorspeelt naar een 3e\nspeler van het team.\nNa elke score draaien de spelers door en komt er een andere\nspeler in het vierkant te staan.\nHet balbezittende team behoudt na een score balbezit, maar de\nbal moet wel eerst weer worden teruggespeeld naar de eigen\nhelft, voordat er opnieuw gescoord kan worden.\nVariatie:\n- in plaats van de derde speler aan te spelen, mag de speler in het\nvierkant zelf met de bal het vierkant uitlopen.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 22\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "SKIPPING MET BAL", "content": "Is een oefening, waarbij de speler de stappen van de\nonderstaande techniek, op de plaats, uitvoert, terwijl hij een bal in\nbeide handen voor zich houdt.Bij elke stap van de skipping raakt\nde speler bij het heffen van zijn knie met zijn bovenbeen de bal.\n1. Skipping (Stap 3 en 4)\nOpgelet!\n- dit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler de stappen 3 en 4 van de skipping beheerst.\nDifferentiatie:\n- uitvoering in voorwaartse richting.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\n- de spelers lopen van 5-meterlijn tot 16-\nmeterlijn in het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek, zie\ntechnieklijst."}, {"type": "techniek", "title": "A. EEN-TWEE OF TECHNIEK; BUITENKANT VOET, VOOR JE (1)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de buitenkant van de voet.\nUit te voeren technieken:\n- Akka (buitenkant-binnen) (Stap 4)\n- Schaar (Stap 6)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de buitenkant van de\nrechtervoet richting speler 1\nE. Speler 2 (doet alsof hij een 1 : 2 wil aangaan met speler 3)\nvoert daar één van onderstaande bewegingen uit:\n- Akka (buitenkant-binnen) (Stap 4)\n- Schaar (Stap 6)\nF. Speler 2 versnelt kort met de bal aan de buitenkant linkervoet\ntot aan de buitenste pylonen\nG. Speler 2 dribbelt rustig terug naar het beginpunt.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 6) en\nAkka (buiten-binnen) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan er start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: MET VOLLEDIGE WEERSTAND EN KAATSER", "content": "Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, gevolgd door het afwerken\nop doel.\nVoer onderstaande oefeningen apart van elkaar uit:\nSpeler 2 dribbelt de bal met de buitenkant van de rechtervoet\nrichting speler 1.\n- Uit te voeren technieken: Akka (buitenkant-binnen) (Stap 4) en\nSchaar (Stap 6)\nSpeler 2 dribbelt de bal met de binnenkant van de rechtervoet\nrichting speler 1.\n- Uit te voeren technieken: Aai buitenkant voet (Stap 6), Sleep\n(Stap 5) en Akka (binnen-voor) (Stap 4)\nSpeler 2 dribbelt de bal met de binnenkant van de linkervoet\nrichting speler 1.\n- Uit te voeren technieken: Uitstappen meenemen (Stap 6) en\nAkka (binnen-buiten) (Stap 4)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af.\nD. Speler 2 dribbelt vervolgens de bal richting speler 1\nE. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 3 of hij passeert hem met één van bovenstaande\ntechnieken\nF. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nG. Speler 2 dribbelt richting doel.\nH. Speler 2 werkt af op doel.\nOpgelet!\nDe spelers 4, 5 en 6 voeren dezelfde oefening uit op het andere\ndoel.\nMaterialen\nAantal spelers: 10-14\nAantal ballen; 6-8\nAantal pylonen: 9\nOnderlinge afstand pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 2 haalt de bal op en sluit achter aan bij\n12.\n- Speler 1 neemt de taak over van speler 3.\n- Speler 3 neemt de taak over van speler 2.\n- Oefening start nu bij speler 7.\n- Idem voor de spelers aan de andere zijde.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger mag binnen het hele vak\nverdedigen.\nAfwerken op doel:\n- Om met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken, moet je de\nsnelheid van de bal juist inschatten.\n- Raak de bal in het hart\n- Houdt spanning in de voet\n- Raakvlak: Afhankelijk van de situatie de bal\nmet de binnenkant of met de volle wreef\nraken\n- Houdt het standbeen iets voorbij de bal,\ndan blijft de bal laag.\n- Houdt het standbeen iets achter de bal en\nraak de bal aan de onderkant, dan gaat de\nbal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O12', 7, '{"session_a": [{"type": "warming_up", "title": "STAP 2.2 B: AANBIEDEN, TOT 45º IN DRIEHOEKSVORM (2)", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich opengedraaid \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich opengedraaid \"naar links\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 speelt naar speler 1\n- speler 1 biedt zich opengedraaid \"naar links\" aan\n- speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 1, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 4-5\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- A1, B1 en C1: Achter de bal aan doorlopen naar\nde volgende pylon.\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "B. EEN-TWEE OF TECHNIEK; BINNENKANT VOET, VOOR JE (1)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de binnenkant van de voet.\nUit te voeren technieken:\n- Aai buitenkant voet (Stap 6)\n- Sleep (Stap 5)\n- Akka (binnen-voor) (Stap 4)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de binnenkant van de\nrechtervoet richting speler 1\nE. Speler 2 (doet alsof hij een 1 : 2 wil aangaan met speler 3)\nvoert daar één van onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 6)\n- Sleep (Stap 5)\n- Akka (binnen-voor) (Stap 4)\nF. Speler 2 versnelt kort met de bal aan buitenkant linkervoet tot\naan de buitenste pylonen\nG. Speler 2 dribbelt rustig terug naar het beginpunt.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 6), Sleep (Stap 5) en Akka (binnen-voor) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 2\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan er start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "3. (6 : 3)", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 3\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 9\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 3:3", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 6\nAantal ballen: veel\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2 mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering."}], "session_b": [{"type": "warming_up", "title": "RATTEN EN RAVEN", "content": "Het spel wordt gespeeld met tweetallen, die recht tegenover\nelkaar staan, op een onderlinge afstand van 2 meter. Aan de ene\nkant staan de ratten en aan andere kant de raven.\nAls verteller vertelt de trainer een verhaal waarin de woorden\nratten en raven steeds voorkomen. Op het moment dat de trainer\néén van deze namen noemt, dan moet die groep zo snel mogelijk\nnaar hun achterlijn zien te lopen.De andere groep moet hen zien\nte tikken voordat zij bij hun achterlijn zijn.\nJe krijgt voor elke getikte speler 1 punt.\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nPylonen:\n- 4 om het speelveld af te bakenen.\n- 4 pylonen/hoedjes om de vrije zone aan te\ngeven.\n- 4 pylonen/hoedjes om de startlijn aan te geven.\n- 2 pylonen/hoedjes op de middenlijn aan te\ngeven\nAanwijzingen\n- als de speler de ander voor de vrije zone\nkan tikken dan heeft die een punt. Speel een\npotje tot de vijf.\n- zorg dat de spelers ook echt starten\nwanneer hun naam genoemd wordt\n- probeer er een leuk verhaal van te maken.\nNiet alleen maar ratten en raven roepen, dus\nspelen met de ''rrrrr''."}, {"type": "techniek", "title": "STAP 2.3 C: INGOOIEN, AANNEMEN-OPENEN, TOT 90º IN PLUSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"voorwaarts\" aan\n- speler 1 gooit de bal in\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1\n- speler 1 biedt zich \"naar rechts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 1 neemt de bal met de binnenkant van de rechtervoet aan.\nC. Speler 1 speelt naar speler 3\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD.Speler 3 dribbelt met de bal om de pylon naar speler 8\n- speler 3 sluit achter speler 8 aan.\nE. Speler 4 start oefening opnieuw.\nF. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\n- Idem, met links aannemen en met links spelen\n- idem, maar nu in tegengestelde richting uitvoeren.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 2\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- na het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nIngooi:\n- beide voeten houden contact met de grond\n- de bal achter het hoofd loslaten\n- beide handen op de bal houden\n- voeten in de richting van het gooien\n- op het juiste been ingooien.\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2.5 B: KOPPEN (SCHUIN) VANUIT EEN VOORWAARTSE BEWEGING", "content": "A. Speler 2 speelt naar speler 1\n- Vanuit het midden gooit speler 2 de bal onderhands schuin aan\nnaar de inlopende speler 1 (op 2-3 meter afstand).\nB. Speler 1 speelt naar speler 2\n- Speler 1 kopt de bal met een één/ tweebenige afzet schuin terug\nin de handen van speler 2.\nC. Speler 2 speelt naar speler 3\n- Idem als A naar speler 3.\nOpgelet!\nIdem voor de spelers 4,5 en 6 in tegenovergestelde richting.\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 3-4\nAantal pylonen: 3\nAfstand van de pylonen: 4m\nDoordraaien:\nB1. Achter de bal aan doorlopen naar de positie\naan de andere kant.\nWisselen van functie naar eigen inzicht.\nAanwijzingen\n- Vroegtijdig afzetten.\n- Afzetbeen terugbrengen in spanboog.\n- Zwaaibeen blijft gebogen voor-hoog.\n- Bal moet op het hoogste punt van de\nsprong worden gekopt (dode punt).\n- Juiste moment bovenlichaam naar voren en\narmen naar achter.\n- Bal raken met het voorhoofd.\n- De bal goed richting geven, door de\nduwbeweging in de richting van speler 2 te\nmaken.\nLIJNDRIBBEL 4:3 MET DOEL\nMethodiek\nd.w.z. dat 4 aanvallers d.m.v. samenspel/ een persoonlijke actie 3\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 4 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger (alleen van\ntoepassing voor teams 11-11).\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nD-pupillen: 30m bij 25m\nC-,B-,A-junioren: 35m bij 30m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gezorgd moet worden dat de\nnummer 3 de vrije man is\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers\nVerdedigers coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O12', 8, '{"session_a": [{"type": "warming_up", "title": "STAP 2.2 C: AANBIEDEN, TOT 90º IN PLUSVORM (2)", "content": "A. Spelers 1 speelt naar speler 2.\n- speler 2 biedt zich \"naar links\"aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 neemt de bal aan en dribbelt naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem in de andere driehoek voor de spelers 5 t/m 8.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan lopen naar de volgende pylon.\nAanwijzingen\nAanbieden:\n- voor de kaats vragen om de bal.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- laag zitten (goed door de knieën)\n- standbeen naast de bal\n- lichaam over de bal\n- bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "C. EEN-TWEE OF TECHNIEK; BINNENKANT ANDERE VOET, VOOR JE (1)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de binnenkant van de andere voet.\nUit te voeren technieken:\n- Uitstappen meenemen (Stap 6)\n- Akka (binnen-buiten) (Stap 4)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de binnenkant van de\nlinkervoet richting speler 1\nE. Speler 2 (doet alsof hij een 1 : 2 wil aangaan met speler 3)\nvoert daar één van onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 6)\n- Akka (binnen-buiten) (Stap 4)\nF. Speler 2 versnelt kort met de bal aan buitenkant linkervoet tot\naan de buitenste pylonen\nG. Speler 2 dribbelt rustig terug naar het beginpunt.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 6) en Akka (binnen-buiten) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 2\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan er start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "2. (4 : 2 + 2)", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de 2 verdedigers de bal kunnen veroveren.\nWanneer de verdedigers de bal onderscheppen dan moeten zij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 2 verdedigers en 2 aanvallers mee naar het andere\nveld. Nu moeten de vier verdedigers d.m.v, samenspel de bal in\nhun bezit zien te houden zonder dat de 2 aanvallers de bal\nkunnen veroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (12m bij 10m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "BELGISCH VOETBAL 6 TEGEN 6 + 2 KEEPERS", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 6 spelers en 1\nkeeper, die tegen elkaar spelen.\nElk team verdedigt één doel. De doelen staan in het midden van\nhet veld met de achterkanten tegen elkaar.\nAls je scoort in het doel van de tegenstander krijg je een punt.\nVariatie:\n- als een team een goede hoge bal kan spelen, evt.toevoegen dat\nde bal niet hoog gepeeld mag worden, of omgekeerd als ze het\nniet kunnen.\nMaterialen\nAantal spelers: 12 + 2 Keepers\nAantal ballen: 5\nAantal pylonen: 4\nDoel: 2\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "KRUISPAS MET BAL", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek, in zijwaartse richting uitvoert(en).\nDe spelers) maakt(en), bij elke voorste voetplaatsing, een\nkruispas met de bal. De speler tikt daarbij de bal met de\nbinnenkant van de voet aan naar voren.\n1. Kruispas (Stap 3)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen gebruikt worden als de\nspeler stap 3 beheerst.\nDifferentiatie:\nBij elke achterste voetplaatsing de bal een tik naar voren geven.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aanpassen aan\nhoeveelheid spelers. Elke speler één bal.\nOrganisatie:\nUitvoering van de achterlijn naar de 16-\nmeterlijn. Dit kan je ook aangeven met pylonen.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.6 C: KAATSEN-OPENEN, TOT 90º IN PLUSVORM (3)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 3\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nD. Speler 3 speelt naar speler 2\n- Idem als beschreven bij C, etc.\nE. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar rechts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nF. Speler 3 dribbelt met de bal om de pylon naar speler 4\n- Speler 3 sluit achter speler 4 aan.\nG. Speler 4 start oefening opnieuw\nH. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\nIdem, maar nu in tegengestelde richting uitvoeren en met links\nuitvoeren.\nMaterialen\nAantal spelers: 8-10\nAantal ballen: 2\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "AANBIEDEN, TOT 90º IN STROOMVORM MET AFWERKEN", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich \"naar links\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3\n- Speler 3 biedt zich \"naar links\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 neemt opengedraaid aan en werkt af op de goal\n-Speler 3 neemt de bal aan richting de goal en dribbelt op\nsnelheid naar de afwerklijn\n-Speler 3 schiet vanaf de afwerklijn op doel\nVariatie in uitvoering:\nIdem, andersom met het andere been.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O12', 9, '{"session_a": [{"type": "warming_up", "title": "KETTINGTIKKERTJE", "content": "Bij dit spel staan alle spelers, met een bal aan de voet, in een vak. Twee spelers\nzijn de tikkers en moeten proberen de spelers uit te tikken door hun bal uit het\nspel te schieten.\nDe eerst afgetikte speler pakt, nadat zijn bal is uitgeschoten de hand van de\ntikker vast. Elke volgende afgetikte speler sluit daarna aan om zo een ketting te\nvormen.\nWelke verdediger behaalt de langste ketting (ofwel wie werken het beste samen?)\nOpmerking:\n- als tijdens het tkken de ketting breekt, dan mag de afgetikte speler gewoon\ndoorspelen.\nLet op:\n- de kettinggrootte mag niet groter worden dan 4 spelers (bij het vaststellen van\nhet resultaat wordt dan het totaal aantal afgetikte spelers geteld).\nMaterialen\nPylonen: 4 pylonen om het speelveld uit te zetten.\nBallen: op een speler na heeft iedere speler een bal\nSpeeltijd: 10- 15 minuten"}, {"type": "techniek", "title": "STAP 2.5 D: AANNEMEN-OPENEN, TOT 135º IN Y-VORM (1)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal met de binnenkant van de linkervoet aan.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 1 speelt naar speler 3.\n- Idem als beschreven bij A, etc.\nD. Speler 3 dribbelt met de bal naar speler 8.\n- Speler 3 wisselt van kant en sluit achter speler 8 aan.\nE. Speler 4 start oefening opnieuw\nF. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 8-12\nAantal ballen: 4-6\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "(6 : 4) OEFENING 1", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\n(Positiespel systeem Ajax)\nWisselen van taak na een aantal minuten (alleen de nummers 4\nen 10 blijven staan) / of na een aantal keer afpakken.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 20m bij 15m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 7:7 + 2 KEEPERS", "content": "Zeven aanvallers moeten d.m.v. samenspel/ individuele actie 7\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij\nopnieuw.opnieuw.\nMaterialen\nAantal spelers:14 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nE-pupillen: 40m bij 35m\nD-pupillen: 45m bij 40m\nC-junioren: 50m bij 45m\nB-,A-junioren: 55m bij 50m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een 1-3-1-3\nformatie.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "TRIPLING MET BAL", "content": "Is een oefening, waarbij de speler de stap van de onderstaande\ntechniek uitvoert, terwijl hij zich voorwaarts beweegt. De speler\nraakt, bij elke voetplaatsing van de tripling, de bal met de punt\nvan de schoen en volgt zo de baan van de bal.\n1. Tripling (Stap 4)\nOpgelet!\nDit is een eindvorm, die alleen kan worden uitgevoerd als de\nspeler de laatste stap van de tripling voldoende beheerst.\nDifferentiatie:\nUitvoering in parcoursvorm, waarbij constant van richting moet\nworden veranderd.\nMaterialen\nAantal spelers: gehele team\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\nDe spelers lopen van achterlijn tot 16-meterlijn\nin het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSKIPPING MET BAL\nMethodiek\nIs een oefening, waarbij de speler de stappen van de\nonderstaande techniek, op de plaats, uitvoert, terwijl hij een bal in\nbeide handen voor zich houdt.Bij elke stap van de skipping raakt\nde speler bij het heffen van zijn knie met zijn bovenbeen de bal.\n1. Skipping (Stap 3 en 4)\nOpgelet!\n- dit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler de stappen 3 en 4 van de skipping beheerst.\nDifferentiatie:\n- uitvoering in voorwaartse richting.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\n- de spelers lopen van 5-meterlijn tot 16-\nmeterlijn in het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek, zie\ntechnieklijst."}, {"type": "techniek", "title": "EEN-TWEE OF TECHNIEK; TEGENSTANDER ACHTER JE", "content": "Techniek uitvoeren met een tegenstander achter je.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander achter je te passeren.\n- Een 1 : 2 aangaan om een tegenstander achter je voorbij te gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nachter je\nUit te voeren technieken:\n- Kappen buitenkant voet (Stap 5)\n- Binnen-buitenkant wegdraai (Stap 6)\n- De Overstap (Stap 6)\nA. Speler 1 passed de bal naar speler 3 die een tegenstander\n(speler 4) in de rug heeft.\nB. Speler 1 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 2 of hij passeert speler 4 met één van bovenstaande\ntechnieken.\nC. Speler 3 dribbelt of loopt door om de bal te ontvangen.\nD. Speler 3 dribbelt over de achterlijn en start de oefening\nopnieuw vanaf de andere kant.\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 6),\nKappen buitenkant voet (Stap 5) en Binnen buiten wegdraai (Stap\n6).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 4\nSpeler 4 neemt de taak over van speler 3.\nSpeler 3 blijft staan en start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger mag het hele vak gebruiken\nom te verdedigen."}, {"type": "techniek", "title": "VERDEDIGEN DOOR AANVALLERS EN MIDDENVELDERS (5 : 6+KEEPER)", "content": "D.w.z. dat 5 aanvallers/ middenvelders door samen te werken in\nbalbezit moeten zien te komen. Daarbij moeten zij ook zo goed\nmogelijk positioneel blijven verdedigen.\nDe verdedigende partij (6 verdedigers /middenvelders+ Keeper)\nkan scoren door de bal over de lijn van één van de doeltjes te\ndribbelen.\nBal afgepakt dan kunnen de aanvallers op het grote doel scoren.\nDe opbouw start altijd bij de doelman\nMaterialen\nAantal spelers: 11+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 30m bij 35m\nD-pupillen: 35m bij 40m\nC-,B-,A-junioren: 40m bij 45m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij verdedigen\ncoachen op:\n- het knijpen en kantelen naar de kant waar\nde bal is\n- het coachen van elkaar (het initiatief ligt bij\nde achterste middenvelder)\n- het dekken vanuit de zone, vanwege de\novertalsituatie.\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het breed maken van het veld.\n- het zoeken van de kortste weg naar het\ndoel om tot scoren te komen."}]}'::jsonb),
('O12', 10, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (1)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.7 B: AANNEMEN (MET HET HOOFD) EN SPELEN TOT 45º (2)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op hoofdhoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 neemt de bal met het voorhoofd aan en speelt de bal\ndirect met de binnenkant van de rechtervoet naar speler 3\nC. Speler 3 speelt naar speler 1\n- Speler 1 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 3 pakt de bal op en gooit de bal onderhands, op\nhoofdhoogte met een boog naar speler 2, etc\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nDeze oefenvorm geldt ook voor: Aannemen met het bovenbeen\nen�met de borst\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 4 m\nD-,C-,B-,A-junioren: 5 m\nAanwijzingen\nAannemen:\n- Open aannemen, in de speelrichting.\n- Bij het aannemen met het hoofd soepel en\nflexibel met de bal meegaan en zodoende bal\n\"dood\" maken.\n- Bal moet voor je liggen, maar binnen bereik\n- Snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "3. (6 : 3)", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 3\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 9\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "HOEK VOETBAL 7 TEGEN 7", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen op een groot vierkant veld, waarvan de\nhoeken gemarkeerd zijn met pylonen.\nIn de hoeken van het veld kan de partij in balbezit scoren. Alleen\nde balbezittende partij mag in deze hoeken komen.\nAls je gescoord hebt behoud je team balbezit en mag je proberen\nin één van de andere hoeken te scoren.\nLET OP:\nEr mag nooit 2x achter elkaar in dezelfde hoek gescoord worden\n(door beide teams niet).\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP (3)", "content": "Is een oefening, waarbij de voorwaartse en zijwaartse vormen\ngecombineerd worden en aangeleerd over de stokken. De\noefening is opgebouwd van grove motoriek naar de fijne motoriek.\nDat wil zeggen binnen de looptraining, er wordt gewerkt van een\nskipping naar skipping 45 graden en vervolgens naar kort\nvoetenwerk.\nEr moet hierbij wel nadrukkelijk worden gelet op het lichtvoetig\nagreren over de stokken. Dat wil zeggen dat alles met de bal van\nde voet wordt uitgevoerd. Ten allen tijden wordt er op de bal van\nde voet gelopen.\nStap 1: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt voorwaarts genomen en vervolgens wordt er met twee\nvoeten teruggestapt, de derde stok wordt zijwaarts genomen en\nde vijfde stok vervolgens weer voorwaarts. De tussen stokken\nworden gelopen met één voet tussen de stokken.\nStap 2: Er wordt met de linkervoet begonnen. De eerste stok\nwordt voorwaarts genomen en vervolgens wordt er met twee\nvoeten teruggestapt, de derde stok wordt zijwaarts genomen en\nde vijfde stok vervolgens weer voorwaarts. De tussen stokken\nworden gelopen met één voet tussen de stokken.\nStap 3: Er wordt met de linkervoet begonnen. De eerste stok\nwordt zijwaarts genomen en vervolgens wordt er met twee voeten\nteruggestapt, de derde stok wordt voorwaarts genomen en de\nvijfde stok vervolgens weer zijwaarts. De tussen stokken worden\ngelopen met één voet tussen de stokken.\nStap 4: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt zijwaarts genomen en vervolgens wordt er met twee voeten\nteruggestapt, de derde stok wordt voorwaarts genomen en de\nvijfde stok vervolgens weer zijwaarts. De tussen stokken worden\ngelopen met één voet tussen de stokken.\nDifferentiatie:\nDe beweging wordt aan beide kanten uitgevoerd. Dat wil zeggen\ndat de zijwaarts rechts en links uitgevoerd moeten worden.\nLet op!\nDe romphouding moet ten allen tijden recht zijn en er moet een\narminzet aanwezig zijn.\nMaterialen\nAantal spelers: het gehele team.\nAantal stokkenparcours:\nEén, bij voorkeur twee.\nAantal pylonnen:\n12\nAantal stokken:\n5\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "A. EEN-TWEE OF TECHNIEK; TEGENSTANDER NAAST JE", "content": "Techniek uitvoeren met een tegenstander naast je.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander naast je te passeren.\n- Een 1 : 2 aangaan om een tegenstander naast je voorbij te gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nnaast je.\nUit te voeren technieken:\n- De Verandering (Stap 5)\n- De Overstap (Stap 6)\nA. Speler 1 speelt de bal op speler 2\nB. Speler 2 dribbelt de bal naar de middelste pylon en speler 3\nloopt hierbij mee.\nC. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 1 of hij passeert speler 3 met één van bovenstaande\ntechnieken.\nD. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nE. Speler 2 dribbelt over de achterlijn.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken De verandering (Stap\n5) en De Overstap (Stap 6).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 3.\nSpeler 3 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1 en\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger (speler 3) mag het hele vak\ngebruiken om te verdedigen.\n- Speler 1 mag de bal alleen vragen op de\nzijlijn."}, {"type": "techniek", "title": "B. EEN-TWEE OF TECHNIEK; TEGENSTANDER NAAST JE", "content": "Techniek uitvoeren met een tegenstander naast je.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander naast je te passeren.\n- Een 1 : 2 aangaan om een tegenstander naast je voorbij te gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nnaast je.\nUit te voeren technieken:\n- Kappen achter het standbeen (Stap 4)\n- Kappen binnenkant voet (Stap 5)\n- Kappen buitenkant voet (Stap 5)\nA. Speler 1 speelt de bal op speler 2\nB. Speler 2 dribbelt de bal naar de middelste pylon en speler 3\nloopt hierbij mee.\nC. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 1 of hij passeert speler 3 met één van bovenstaande\ntechnieken.\nD. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nE. Speler 2 dribbelt over de achterlijn.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Kappen binnenkant\nvoet (Stap 5), Kappen buitenkant voet (Stap 5) en Kappen achter\nstandbeen (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 3.\nSpeler 3 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1 en\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger (speler 3) mag het hele vak\ngebruiken om te verdedigen.\n- Speler 1 mag de bal alleen vragen op de\nzijlijn."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O12', 11, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (2)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.5 D: AANNEMEN-OPENEN, TOT 135º IN Y-VORM (1)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal met de binnenkant van de linkervoet aan.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 1 speelt naar speler 3.\n- Idem als beschreven bij A, etc.\nD. Speler 3 dribbelt met de bal naar speler 8.\n- Speler 3 wisselt van kant en sluit achter speler 8 aan.\nE. Speler 4 start oefening opnieuw\nF. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 8-12\nAantal ballen: 4-6\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "(6 : 4) OEFENING 2", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\n(Positiespel systeem Ajax)\nBij balverlies direct omschakelen. De middelste 4 nemen de\nposities over aan de zijkanten en het positiespel gaat gewoon\nverder.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 20m bij 15m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "OMSCHAKELINGSTIKKERTJE", "content": "Bij deze oefening wordt de omschakeling van voetballers getraind.\nDe spelers worden hierbij in 2 groepen van elk 6 spelers verdeeld. Eén groep is\nvoorzien van een hesje. Elke speler uit de ene groep vormt een tweetal met een\nspeler uit de andere groep.\nOp een teken van de trainer probeert de speler uit de ene groep de andere\nspeler van het tweetal uit de andere groep te tikken.\nNadat hij hem getikt heeft draait hij direct van hem weg en versnelt naar de\nzijlijn. De andere speler probeert op zijn beurt de eerste speler, nog voordat hij\nde zijlijn heeft gepasseerd, te tikken.\nDifferentiatie gemakkelijk:\n- het spel “koe-kopen”.\nDifferentiatie moeilijk:\n- er kan gevarieerd worden door spelers met een bal aan de zijlijn te laten staan,\nom een kaats aan te gaan met de weggedraaide speler. Hij komt hierbij als het\nware in de bal. Omschakeling met bal (1)\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 12\nOrganisatie:\n- de afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "STAP 2.3 D: INGOOIEN, AANNEMEN-OPENEN, TOT 135º IN LIJNVORM", "content": "A. Speler 1 speelt naar speler 2.\n- speler 2 biedt zich \"voorwaarts\" aan\n- speler 1 gooit de bal in\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1.\n- speler 1 biedt zich \"naar rechts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC.Speler 1 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nE. Speler 4 start oefening opnieuw\nF. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links\n- speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 8-12\nAantal ballen: 4\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- na het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nIngooi:\n- beide voeten houden contact met de grond\n- de bal achter het hoofd loslaten\n- beide handen op de bal houden\n- voeten in de richting van het gooien\n- op het juiste been ingooien.\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2.5 C: KOPPEN MET SPRONG VANUIT EEN VOORWAARTSE BEWEGING", "content": "A. Speler 2 speelt naar speler 1\n- Vanuit het midden gooit speler 2 de bal onderhands schuin aan\nop het hoofd van de inlopende speler 2 (op 2-3 meter afstand).\nB. Speler 1 speelt naar speler 3\n- Speler 1 kopt de bal met een één/ tweebenige afzet schuin door\nin de handen van speler 3.\nC. Speler 3 speelt naar speler 4\n- Idem als A naar speler 4, maar nu vanaf de andere kant.\nD. Speler 4 speelt naar speler 2\n- Idem als B naar speler 2, etc.\nOpgelet!\nIdem voor de spelers 5,6,7 en 8 in tegenovergestelde richting.\nMaterialen\nAantal spelers: 6-8\nAantal ballen: 3-4\nAantal pylonen: 6\nAfstand van de pylonen: 4m\nDoordraaien:\nB1. Achter de bal aan doorlopen naar de positie\naan de andere kant.\nWisselen van functie naar eigen inzicht.\nAanwijzingen\n- Vroegtijdig afzetten.\n- Afzetbeen terugbrengen in spanboog.\n- Zwaaibeen blijft gebogen voor-hoog.\n- Bal moet op het hoogste punt van de\nsprong worden gekopt (dode punt).\n- Juiste moment bovenlichaam naar voren en\narmen naar achter.\n- Bal raken met het voorhoofd.\n- De bal goed richting geven, door de\nduwbeweging in de richting van speler 3 te\nmaken.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O12', 12, '{"session_a": [{"type": "warming_up", "title": "PAALTJES VOETBAL 2", "content": "Het spel wordt gespeeld met tweetallen, elk met 1 pylon en een\nbal. De ene speler is verdediger en de ander aanvaller. De\naanvaller moet proberen 1 punt te scoren door de pylon omver te\nschieten. De verdediger probeert dit te voorkomen.\nOpgelet!\n- Na een aantal minuten wisselen van functie.\n- De spelers moeten binnen het afgebakende veld blijven.\nVariatie:\nBij een score wisselen alle spelers tegelijk van functie\nMaterialen\nDuur:10-15 min\nAantal: 2 of meer spelers\nPylon: voor ieder tweetal 1\nBallen: 1-2\nAanwijzingen\nZorg dat de spelers niet voor de pylon blijven\nhangen.\nSTAP 2.8 B: KAATSEN HOOG (MET BINNENKANT VOET) TOT 45º (1)\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet in de handen van speler 3, etc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- Open draaien, naar de speelrichting.\n- De bal met de juiste snelheid/richting door\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "2. (4 : 2 + 2)", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de 2 verdedigers de bal kunnen veroveren.\nWanneer de verdedigers de bal onderscheppen dan moeten zij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 2 verdedigers en 2 aanvallers mee naar het andere\nveld. Nu moeten de vier verdedigers d.m.v, samenspel de bal in\nhun bezit zien te houden zonder dat de 2 aanvallers de bal\nkunnen veroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (12m bij 10m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "RUIMTE VOETBAL 7 TEGEN 7", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen op een groot veld (ca. half voetbalveld).\nBeide teams verdedigen één kant van het veld, met daarop 2\ngrote poorten (min. 8 m. breed), die ca. 8 m. vanaf de achterlijn\nstaan.\nHet team in balbezit kan scoren door, zonder tussenkomst van de\ntegenstander, de bal naar elkaar over te spelen en daarna te\nscoren in één van de 2 poorten aan de lange zijde van de\ntegenstander..\nOpgelet:\n- men houdt balbezit na het score\n- er kan van beide kanten door de poorten worden gescoord.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "REACTIE-ACTIE", "content": "Dit is een oefening voor het hele team. Het hele team zit/ ligt hierbij op de\nachterlijn van het 16-metergebied. Op een teken van de trainer (b.v. “JA”) staan\nde spelers op en versnellen naar de overkant.\nDifferentiatie:\n- varieer in de uitgangshouding, zoals zitten op de billen, liggen op de buik, -\nzijde (beide kanten) of op de rug.\nWees daarbij creatief!\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: gehele team.\nOrganisatie:\nAchterlijn 16-meter gebied."}, {"type": "techniek", "title": "STAP 2.5 D: AANNEMEN-OPENEN, TOT 135º IN Y-VORM (2)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal met de binnenkant van de linkervoet aan.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 1 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Idem als beschreven bij B, etc.\nD. Speler 3 speelt naar speler 2.\n- Idem als beschreven bij C, etc.\nE. Speler 2 speelt naar speler 3.\n- Speler 3 biedt zich \"naar links\" aan.\n- Idem als beschreven bij B, etc.\nF. Speler 3 dribbelt met de bal naar speler 8.\n- Speler 3 wisselt van kant en sluit achter speler 8 aan.\nG. Speler 4 start oefening opnieuw\nH. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 8-12\nAantal ballen: 4-6\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "TEGENSTANDER NAAST JE: MET WEERSTAND", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- De verandering (Stap 4B)\n- Kappen achter het standbeen (Stap 3B)\n- Kappen binnenkant voet (Stap 4B)\n- Kappen buitenkant voet (Stap 4B)\n- De Overstap (Stap 5B)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen (heeft daarbij een\ntegenstander, speler 2, die met hem mee oploopt).\nB. Ter hoogte daarvan voert speler 1 één van de bovengenoemde\ntechnieken uit en passeert daarmee de mee opgelopen\ntegenstander.\nC. Daarna dribbelt hij, met de bal aan de voet, richting het doel\nom vervolgens hierop af te ronden.\nD. Speler 1 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 haalt de bal en sluit achter in de\nandere rij aan.\n- Speler 2 loopt terug en start nu de oefening.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "techniek", "title": "NIET IN HET WATER 7 TEGEN 7", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen.\nIn het veld staan 2 doelen met de achterkanten naar elkaar toe.\nTussen de doelen is een vak (water), waar geen spelers mogen\nkomen. De bal mg wel door het vak gespeeld worden.\nHet team dat scoort in het doel van de tegenstander krijgt 1 punt.\nOpgelet:\n- als een speler door het water loopt, krijgt de tegenstander een\nvrije bal op de achterlijn, aan de kant van het doel waar zij\nmoeten scoren.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 8\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O12', 13, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (1)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Schaar (Stap 4)\n- Akka (buiten-binnen) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.8 B: KAATSEN HOOG (MET BINNENKANT VOET) TOT 45º (1)", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet in de handen van speler 3, etc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- Open draaien, naar de speelrichting.\n- De bal met de juiste snelheid/richting door\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(6 : 4) OEFENING 2", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\n(Positiespel systeem Ajax)\nBij balverlies direct omschakelen. De middelste 4 nemen de\nposities over aan de zijkanten en het positiespel gaat gewoon\nverder.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 20m bij 15m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "BELGISCH VOETBAL 6 TEGEN 6 + 2 KEEPERS", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 6 spelers en 1\nkeeper, die tegen elkaar spelen.\nElk team verdedigt één doel. De doelen staan in het midden van\nhet veld met de achterkanten tegen elkaar.\nAls je scoort in het doel van de tegenstander krijg je een punt.\nVariatie:\n- als een team een goede hoge bal kan spelen, evt.toevoegen dat\nde bal niet hoog gepeeld mag worden, of omgekeerd als ze het\nniet kunnen.\nMaterialen\nAantal spelers: 12 + 2 Keepers\nAantal ballen: 5\nAantal pylonen: 4\nDoel: 2\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "SKIPPING MET BAL", "content": "Is een oefening, waarbij de speler de stappen van de\nonderstaande techniek, op de plaats, uitvoert, terwijl hij een bal in\nbeide handen voor zich houdt.Bij elke stap van de skipping raakt\nde speler bij het heffen van zijn knie met zijn bovenbeen de bal.\n1. Skipping (Stap 3 en 4)\nOpgelet!\n- dit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler de stappen 3 en 4 van de skipping beheerst.\nDifferentiatie:\n- uitvoering in voorwaartse richting.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\n- de spelers lopen van 5-meterlijn tot 16-\nmeterlijn in het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek, zie\ntechnieklijst.\nKRUISPAS MET BAL\nMethodiek\nIs een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek, in zijwaartse richting uitvoert(en).\nDe spelers) maakt(en), bij elke voorste voetplaatsing, een\nkruispas met de bal. De speler tikt daarbij de bal met de\nbinnenkant van de voet aan naar voren.\n1. Kruispas (Stap 3)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen gebruikt worden als de\nspeler stap 3 beheerst.\nDifferentiatie:\nBij elke achterste voetplaatsing de bal een tik naar voren geven.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aanpassen aan\nhoeveelheid spelers. Elke speler één bal.\nOrganisatie:\nUitvoering van de achterlijn naar de 16-\nmeterlijn. Dit kan je ook aangeven met pylonen.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "EEN-TWEE OF TECHNIEK; TEGENSTANDER VANAF DE ZIJKANT", "content": "Techniek uitvoeren met een tegenstander vanaf de zijkant.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander vanaf de zijkant te\npasseren.\n- Een 1 : 2 aangaan om een tegenstander vanaf de zijkant voorbij\nte gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nvanaf de zijkant.\nUit te voeren technieken:\n- 2x Kappen buitenkant voet (Stap 5)\n- Pirouette (Stap 7)\n- Aai kappen achter het standbeen(Stap 6)\n- De Schijntrap (Stap 6)\nA. Speler 1 speelt de bal op speler 2\nB. Speler 2 dribbelt de bal naar de middelste pylon en speler 3\nkomt vanaf de zijkant aanlopen.\nC. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 1 of hij passeert speler 3 met één van bovenstaande\ntechnieken.\nD. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nE. Speler 2 dribbelt over de achterlijn.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 5: Het oefenen van de technieken Aai kappen achter\nstandbeen (Stap 6), Kappen buitenkant voet (Stap 5), Pirouette\n(Stap 7) en De schijntrap (Stap 6).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 3.\nSpeler 3 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1 en\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger (speler 3) mag het hele vak\ngebruiken om te verdedigen.\n- Speler 1 mag de bal alleen vragen op de\nachterlijn."}, {"type": "techniek", "title": "VERDEDIGEN DOOR MIDDENVELDERS EN VERDEDIGERS (5+KEEPER : 6)", "content": "D.w.z. dat 6 aanvallers/ middenvelders d.m.v. samenspel moeten\nzien te scoren op het grote doel.\nDe 5 verdedigers/ middenvelders + keeper moeten daarbij d.m.v.\nsamenwerken zo goed mogelijk positioneel verdedigen.\nBal afgepakt dan kunnen de verdedigers scoren door de bal over\nde lijn van één van de doeltjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 11+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 30m bij 35m\nD-pupillen: 35m bij 40m\nC-,B-,A-junioren: 40m bij 45m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nVerdedigers/middenvelders bij verdedigen\ncoachen op:\n- het inzakken van de middenvelder en het\nuitverdedigen vanuit de zone naar de kant\nvan de bal\n- het knijpen en kantelen van de verdedigers,\ndaar waar nodig\n- het gebruik maken van de buitenspelval het\ncoachen van elkaar(het initiatief ligt bij de\nachterste speler)."}]}'::jsonb),
('O12', 14, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN LIJNVORM (2)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler dribbelt richting overstaande pylon\n- Speler dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 4)\n- Sleep (Stap 3)\n- Akka (binnen-voor) (Stap 2)\n- Uitstappen meenemen (Stap 4)\n- Akka (binnen-buiten) (Stap 2)\nC. Speler dribbelt verder en herhaald deze stappen tot aan de\npylon.\nIdem terug.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: alle\nAantal ballen: per speler 1 bal\nAantal pylonen: 4\nOnderlinge afstand pylonen: 15 mtr.\nDoordraaien:\nIdem, maar nu uitvoeren met het andere been.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.6 D: KAATSEN-OPENEN, TOT 135º IN Y-VORM (1)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.]\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD. Speler 3 dribbelt met de bal naar speler 8.\n- Speler 3 wisselt van kant ensluit achter speler 8 aan.\nE. Speler 4 start oefening opnieuw\nF. Spelers 5, 6, 7 en 8\n- Idem als beschreven bij A. B. C en D,etc.\nOpgelet!\nIdem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\nSpeler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 8-12\nAantal ballen: 4-6\nAantal pylonen: 5\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "3. (6 : 3)", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 3\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 9\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "KANTELEN VOETBAL 7 TEGEN 7", "content": "Deze oefening wordt uitgevoerd met 2 teams van elk 7 spelers,\nwaarbij van elk team 1 speler in één van de 2 vierkanten staat.\nHet team in balbezit kan scoren door hun speler in het vierkant\naan te spelen, die vervolgens de bal doorspeelt naar een 3e\nspeler van het team.\nNa elke score draaien de spelers door en komt er een andere\nspeler in het vierkant te staan.\nHet balbezittende team behoudt na een score balbezit, maar de\nbal moet wel eerst weer worden teruggespeeld naar de eigen\nhelft, voordat er opnieuw gescoord kan worden.\nVariatie:\n- in plaats van de derde speler aan te spelen, mag de speler in het\nvierkant zelf met de bal het vierkant uitlopen.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 22\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "UIT DE RUG", "content": "Oefeningen, waarbij de spelers voor elkaar staan. De voorste speler staat hierbij\nin een vak van 2 bij 3 meter.\nDe achterste speler probeert, door plotseling te versnellen, uit de rug van de\nvoorste speler te komen en zonder getikt te worden de finishlijn te behalen.\nOpgelet!\nHet is een reactiespel, waarbij de jongste jeugd spelenderwijs het spel wordt\naangeleerd.\nLater, bij de oudere jeugd, kan daar goed gebruik van worden gemaakt.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 6\nAantal ballen: 0\nOrganisatie:\nDe spelers staan voor elkaar. Bij deze oefening ligt het initiatief ligt bij de\nachterste speler."}, {"type": "techniek", "title": "A. EEN-TWEE OF TECHNIEK; BUITENKANT VOET, VOOR JE (1)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de buitenkant van de voet.\nUit te voeren technieken:\n- Akka (buitenkant-binnen) (Stap 4)\n- Schaar (Stap 6)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de buitenkant van de\nrechtervoet richting speler 1\nE. Speler 2 (doet alsof hij een 1 : 2 wil aangaan met speler 3)\nvoert daar één van onderstaande bewegingen uit:\n- Akka (buitenkant-binnen) (Stap 4)\n- Schaar (Stap 6)\nF. Speler 2 versnelt kort met de bal aan de buitenkant linkervoet\ntot aan de buitenste pylonen\nG. Speler 2 dribbelt rustig terug naar het beginpunt.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 6) en\nAkka (buiten-binnen) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan er start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "OEFENING 4", "content": "De spelers staan hierbij in twee rijen opgesteld.\nA. Speler 1 speelt de bal met de binnenkant van de rechtervoet op\naanbiedende speler 2 en loopt daarna door in de richting van het\ndoel.\nB. Speler 2 loopt na het afspelen van de bal direct voorwaarts om\nde bal weer van speler 1 in de loop aangespeeld te krijgen.\nC. Speler 1 speelt de bal vervolgens in de loop van speler 2.\nD. Speler 2 neemt de bal in de loop mee (verplicht 1x raken) en\nwerkt de bal af op het doel.\nOpgelet!\nDe volgende speler start pas nadat er op doel geschoten is.\nDe spelers moeten de bal in één keer schieten en vooral niet stil\ngaan staan om te schieten.\nVariatie in uitvoering:\nWisselen van kant; wisselen van kant is wisselen van speelbeen.\nMaterialen\nAantal spelers: 8 -12\nAantal ballen: voldoende\nDoel: 1 (7.32m bij 2.44m)\nAantal pylonen: 2\nFictieve buitenspellijn: 1\nDoordraaien:\n- Speler 1 neemt de taak over van speler 2.\n- Speler 2 haalt de bal en sluit achter in de rij\nvan speler 1 aan.\n- Idem voor de andere rij.\nAanwijzingen\n- Het aanspelen van de bal met de juiste\nsnelheid en op het juiste moment\n- Het rustig beginnen en het langzaam\nopvoeren van de handelingssnelheid\n- Het uiteindelijk komen tot 1 x raken en\nafronden op het doel\n- Het spelen op buitenspel en dus het juiste\nmoment kiezen bij het aanbieden\n- Rekening houden met de buitenspellijn door\nbreed, met het gezicht richting doel, weg te\nlopen door speler 2."}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O12', 15, '{"session_a": [{"type": "warming_up", "title": "STAP 2.1 C: AANBIEDEN, TOT 90º (ZELFDE BEEN) IN VIERKANTSVORM", "content": "A. Speler 1 speelt naar speler 2\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan\nB. Speler 2 speelt naar speler 3\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 speelt naar speler 4\n- idem als beschreven bij A, etc.\nVariatie in uitvoering:\n- idem, andersom met het andere been.\nVariatie in aanbieden:\n- naar rechts\n- achterwaarts\n- voorwaarts\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "B. EEN-TWEE OF TECHNIEK; BINNENKANT VOET, VOOR JE (1)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de binnenkant van de voet.\nUit te voeren technieken:\n- Aai buitenkant voet (Stap 6)\n- Sleep (Stap 5)\n- Akka (binnen-voor) (Stap 4)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de binnenkant van de\nrechtervoet richting speler 1\nE. Speler 2 (doet alsof hij een 1 : 2 wil aangaan met speler 3)\nvoert daar één van onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 6)\n- Sleep (Stap 5)\n- Akka (binnen-voor) (Stap 4)\nF. Speler 2 versnelt kort met de bal aan buitenkant linkervoet tot\naan de buitenste pylonen\nG. Speler 2 dribbelt rustig terug naar het beginpunt.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 6), Sleep (Stap 5) en Akka (binnen-voor) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 2\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan er start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "(6 : 4) OEFENING 2", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\n(Positiespel systeem Ajax)\nBij balverlies direct omschakelen. De middelste 4 nemen de\nposities over aan de zijkanten en het positiespel gaat gewoon\nverder.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 20m bij 15m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 7:7", "content": "Zeven aanvallers moeten d.m.v. samenspel/ individuele actie 7\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij\nopnieuw.opnieuw.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nE-pupillen: 35m bij 40m\nD-pupillen: 40m bij 45m\nC-junioren: 45m bij 50m\nB-,A-junioren: 50m bij 55m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een 3-1-3 formatie.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering."}], "session_b": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen\nSPRINTTEST\nMethodiek\nVoor deze test wordt in de breedte van het strafschopgebied, op\neen onderlinge afstand van tekens 10 meter, met 5 pylonen een\nparcours uitgezet.\nDe spelers starten de sprint vanaf de zijkant van het “16-\nmetergebied” vanuit stilstand en sprinten vervolgens om de\neerste pylon heen weer terug, gevolgd door een sprint om de\ntweede pylon heen en weer terug. Idem om de derde en de vierde\npylon.\nDe behaalde eindtijd wordt gemeten en vastgelegd.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen: 5\nAfstand tussen de pylonen: 10 mtr.\n1 stopwatch\nSchrijfbenodigdheden.\n- deze test heeft tot doel om de “reactie/\nacceleratie- en/of de maximale snelheid” te\ntoetsen/meten.\nAanwijzingen\n- zowel heen als terug een zo hoog mogelijke\nsnelheid ontwikkelen\n- kort om de pylon draaien\n- neem minimaal 2-3 minuten rust tussen\ntwee testen."}, {"type": "techniek", "title": "HOEK VOETBAL 7 TEGEN 7", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen op een groot vierkant veld, waarvan de\nhoeken gemarkeerd zijn met pylonen.\nIn de hoeken van het veld kan de partij in balbezit scoren. Alleen\nde balbezittende partij mag in deze hoeken komen.\nAls je gescoord hebt behoud je team balbezit en mag je proberen\nin één van de andere hoeken te scoren.\nLET OP:\nEr mag nooit 2x achter elkaar in dezelfde hoek gescoord worden\n(door beide teams niet).\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O12', 16, '{"session_a": [{"type": "warming_up", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º IN Y-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- speler 2 biedt zich \"voorwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- speler 3 wisselt van kant ensluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen door in de andere rij aan te sluiten.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "C. EEN-TWEE OF TECHNIEK; BINNENKANT ANDERE VOET, VOOR JE (1)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de binnenkant van de andere voet.\nUit te voeren technieken:\n- Uitstappen meenemen (Stap 6)\n- Akka (binnen-buiten) (Stap 4)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de binnenkant van de\nlinkervoet richting speler 1\nE. Speler 2 (doet alsof hij een 1 : 2 wil aangaan met speler 3)\nvoert daar één van onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 6)\n- Akka (binnen-buiten) (Stap 4)\nF. Speler 2 versnelt kort met de bal aan buitenkant linkervoet tot\naan de buitenste pylonen\nG. Speler 2 dribbelt rustig terug naar het beginpunt.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 6) en Akka (binnen-buiten) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 2\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan er start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "2. (4 : 2 + 2)", "content": "Vier aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de 2 verdedigers de bal kunnen veroveren.\nWanneer de verdedigers de bal onderscheppen dan moeten zij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 2 verdedigers en 2 aanvallers mee naar het andere\nveld. Nu moeten de vier verdedigers d.m.v, samenspel de bal in\nhun bezit zien te houden zonder dat de 2 aanvallers de bal\nkunnen veroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 8\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (12m bij 10m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- druk op de bal geven zodat de aanvallers\neen fout maken\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP TIKKERTJE", "content": "Bij deze oefening staan de spelers verdeeld in 2 groepen van elk 6 spelers\ntegenover elkaar aan beide zijden van het “stokken-parcours”.\nAan het eind van beide parcoursen staan twee verschillend gekleurde pylonen\nmet aan weerszijden op 10 meter afstand daarvan nog een pylon.\nEr wordt tegelijkertijd gestart met het stokkenparcours(foutloos lopen, anders\nopnieuw).\nDe eerste aangekomene tikt een pylon aan en kiest vervolgens een richting.\nDe laatst aangekomene moet nadat hij de pylon heeft aangetikt de ander\nproberen in te halen en te tikken.\nLet op!\nBij beheersing van het stokkenparcours kan er op snelheid wordt gewerkt.\nMaterialen\nAantal spelers: 12\nAantal pylonen: 24\nOrganisatie:\nDe spelers staan tegenover elkaar met een ruimte er tussen van 20 á 25 meter.\nDe onderlinge afstanden van het stokkenparcours moet even groot zijn.\nSTAP 2.8 B: KAATSEN HOOG (MET BINNENKANT VOET) TOT 45º (1)\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet in de handen van speler 3, etc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- Open draaien, naar de speelrichting.\n- De bal met de juiste snelheid/richting door\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "TEGENSTANDER VANAF DE ZIJKANT: MET WEERSTAND", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4B)\n- Pirouette (Stap 6B)\n- Aai-kappen achter het standbeen (Stap 5B)\n- Schijntrap (Stap 5B)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan komt een tegenstander (speler 2) vanaf de\nzijkant op hem inlopen. Hij passeert vervolgens de tegenstander\nmet één van de bovengenoemde technieken.\nC. Daarna controleert hij de bal en rond vervolgens af op het doel.\nD. Speler 2 haalt de bal en sluit achter in de andere rij aan en\nspeler 1 neemt de taak over van speler 2.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Speler 1 neemt de taak over van speler 2, etc.\n- Idem aan de andere kant.\nAanwijzingen\nVoor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O12', 17, '{"session_a": [{"type": "warming_up", "title": "SNIJ TIKKERTJE", "content": "Eén speler probeert als tikker de andere spelers te tikken. De\ntikker moet, als een andere speler de achtervolging doorkruist,\nvan achtervolgde wisselen. Hij moet nu de andere speler gaan\nachtervolgen.\nOpgelet!\n- naar eigen inzicht wisselen van tikker.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 6-12 spelers\nPylonen: 4 om het speelveld af te bakenen.\nAanwijzingen\n- een getikte wordt de nieuwe tikker.\n- de tikker bepaald van te voren wie hij gaat\ntikken.\n- dit spel kan verwarring veroorzaken. Houd\nde lijn van kruisen goed in de gaten."}, {"type": "techniek", "title": "STAP 2.5 E: AANNEMEN-OPENEN, TOT 180º IN LIJNVORM", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 1 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\n- Idem, andersom maar nu oefening met links uitvoeren.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler. Speler 3 start met dezelfde\noefening maar dan aan de andere kant.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "3. (5 : 2 + 3)", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de 2 verdedigers de bal kunnen veroveren.\nWanneer de verdedigers de bal onderscheppen dan moeten zij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 2 verdedigers en 2 aanvallers mee naar het andere\nveld. Nu moeten de vijf verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de 2 aanvallers de bal\nkunnen veroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (15m bij 12m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 7:7", "content": "Zeven aanvallers moeten d.m.v. samenspel/ individuele actie 7\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij\nopnieuw.opnieuw.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nE-pupillen: 35m bij 40m\nD-pupillen: 40m bij 45m\nC-junioren: 45m bij 50m\nB-,A-junioren: 50m bij 55m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een 3-1-3 formatie.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering."}], "session_b": [{"type": "warming_up", "title": "KRUISPAS MET BAL", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek, in zijwaartse richting uitvoert(en).\nDe spelers) maakt(en), bij elke voorste voetplaatsing, een\nkruispas met de bal. De speler tikt daarbij de bal met de\nbinnenkant van de voet aan naar voren.\n1. Kruispas (Stap 3)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen gebruikt worden als de\nspeler stap 3 beheerst.\nDifferentiatie:\nBij elke achterste voetplaatsing de bal een tik naar voren geven.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aanpassen aan\nhoeveelheid spelers. Elke speler één bal.\nOrganisatie:\nUitvoering van de achterlijn naar de 16-\nmeterlijn. Dit kan je ook aangeven met pylonen.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nSTAP 2.7 C: AANNEMEN (MET HET HOOFD) EN SPELEN TOT 90º\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op hoofdhoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 neemt de bal met het voorhoofd aan en speelt de bal\ndirect door met de binnenkant van de rechtervoet naar speler 3,\netc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 4 m\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAannemen:\n- Open aannemen, in de speelrichting.\n- Bij het aannemen met het hoofd soepel en\nflexibel met de bal meegaan en zodoende bal\n\"dood\" maken.\n- Bal moet voor je liggen, maar binnen bereik\n- Snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "OPBOUW DOOR VERDEDIGERS EN MIDDENVELDER (6+KEEPER : 5)", "content": "D.w.z. dat 6 verdedigers/ middenvelders+ keeper d.m.v.\nsamenspel 5 aanvallers/ middenvelders uitspelen, om daarna de\nbal over de lijn van één van de doeltjes te dribbelen.\nBal afgepakt dan kunnen de aanvallers op het grote doel scoren.\nDe opbouw start altijd bij de doelman.\nMaterialen\nAantal spelers: 11+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 30m bij 35m\nD-pupillen: 35m bij 40m\nC-,B-,A-junioren: 40m bij 45m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nVerdedigers/middenvelders bij opbouw\ncoachen op:\n- het breed maken van het veld door de\nverdedigers. Wordt één van de verdedigers\nin gespeeld dan knijpt de ander naar binnen\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (2+5)\n- het diep weglopen van de centrale\nmiddenvelder en het in de bal komen van de\nandere middenvelder (6+8)\n- het benutten van een overtalsituatie\nVerdedigers/middenvelders bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O12', 18, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (1)", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- Schaar (Stap 5A)\n- Akka (buiten-binnen) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- Het moment waarop je de beweging inzet is\nafhankelijk van de snelheid van het dribbelen\n(eerder of later inzetten).\n- Je mag de tegenstander, bij de uitvoering\nvan de oefening, niet raken."}, {"type": "techniek", "title": "STAP 2.6 E: KAATSEN-OPENEN, TOT 180º IN LIJNVORM", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\n- Idem, andersom maar nu oefening met links uitvoeren.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(6 : 4) OEFENING 1", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\n(Positiespel systeem Ajax)\nWisselen van taak na een aantal minuten (alleen de nummers 4\nen 10 blijven staan) / of na een aantal keer afpakken.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 20m bij 15m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "HOEK VOETBAL 7 TEGEN 7", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen op een groot vierkant veld, waarvan de\nhoeken gemarkeerd zijn met pylonen.\nIn de hoeken van het veld kan de partij in balbezit scoren. Alleen\nde balbezittende partij mag in deze hoeken komen.\nAls je gescoord hebt behoud je team balbezit en mag je proberen\nin één van de andere hoeken te scoren.\nLET OP:\nEr mag nooit 2x achter elkaar in dezelfde hoek gescoord worden\n(door beide teams niet).\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "BESCHERMINGSTIKKERTJE", "content": "Bij deze oefening probeert de tikker een, door de overige 4 spelers,\nafgeschermde speler af te tikken. Door goed samen te werken moeten zij het\ntikken zien te voorkomen.\nOpgelet!\nDit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: 6\nOrganisatie:\nDe afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "EEN-TWEE OF TECHNIEK; TEGENSTANDER ACHTER JE", "content": "Techniek uitvoeren met een tegenstander achter je.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander achter je te passeren.\n- Een 1 : 2 aangaan om een tegenstander achter je voorbij te gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nachter je\nUit te voeren technieken:\n- Kappen buitenkant voet (Stap 5)\n- Binnen-buitenkant wegdraai (Stap 6)\n- De Overstap (Stap 6)\nA. Speler 1 passed de bal naar speler 3 die een tegenstander\n(speler 4) in de rug heeft.\nB. Speler 1 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 2 of hij passeert speler 4 met één van bovenstaande\ntechnieken.\nC. Speler 3 dribbelt of loopt door om de bal te ontvangen.\nD. Speler 3 dribbelt over de achterlijn en start de oefening\nopnieuw vanaf de andere kant.\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 6),\nKappen buitenkant voet (Stap 5) en Binnen buiten wegdraai (Stap\n6).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 4\nSpeler 4 neemt de taak over van speler 3.\nSpeler 3 blijft staan en start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger mag het hele vak gebruiken\nom te verdedigen."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: MET WEERSTAND EN KAATSER", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4B)\n- De Overstap (Stap 5B)\n- Binnen-buitenkant wegdraai (Stap 5)\nA. Speler 1 start de oefening door de bal met de rechter\nbinnenkant van de voet op speler 2 te passen (deze heeft een\ntegenstander, speler 3, in de rug).\nB. Speler 2 ontvangt de bal en passeert vervolgens met één van\nde bovengenoemde technieken de in zijn rug staande verdediger.\nC. Daarna speelt hij de bal, voor een kaats, op speler 4 en loopt\ndoor om de bal te ontvangen.\nD. Vervolgens kaatst speler 4 kaats de bal op de doorgelopen\nspeler 2.\nE. Speler 2 controleert/werkt af op doel of werkt direct af op doel.\nF. Speler 4 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 6,7,8,9 en 10 voeren dezelfde oefening uit op het\nandere doel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nAfstand kaatser vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 loopt door naar de volgende pylon en\nneemt de positie over van speler 3.\n- Speler 2 neemt de positie over van speler 4.\n- Speler 3 neemt de positie over van speler 2.\n- Speler 4 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Juist inschatten van de snelheid van de bal\nom met je passen goed uit te komen, zodat\nje direct op doel kunt afwerken.\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Afhankelijk van de situatie met\nde binnenkant of met de volle wreef\n- Standbeen iets voorbij de bal dan blijft de\nbal laag.\n- Standbeen iets achter de bal en raak de bal\naan de onderkant, dan gaat de bal omhoog."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers: 6\nAantal ballen: veel\nAantal pylonen: 12\nAfstand tussen pylonen:\nF-pupillen: 12m bij 18m\nE-pupillen: 15m bij 20m\nD-pupillen: 20m bij 25m\nC-junioren: 25m bij 30m\nB-,A-junioren: 30m bij 35m\nDoel: 4 (2 mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O12', 19, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (2)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant rechter voet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Uitstappen meenemen (Stap 5A)\n- Akka (binnen-voor) (Stap 3A)\n- Akka (binnen-buiten) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.8 C: KAATSEN HOOG (MET BINNENKANT VOET) TOT 90º", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet in de handen van speler 3, etc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- Open draaien, naar de speelrichting.\n- De bal met de juiste snelheid/richting door\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "3. (6 : 3)", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 3\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 9\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "HIELAANSLAG-ESTAFETTE", "content": "Is een oefening, waarbij de speler(s) de stap van de onderstaande\ntechniek in voorwaartse richting uitvoert(en) tot bij de medespeler\naan de andere kant. Ondertussen voert hij daarbij de hielslag uit,\nterwijl hij de bal met een lichte hoek in de ellebogen in de handen\nvoor het lichaam houdt. Aan de overkant gekomen geeft hij de bal\nover en zijn medespeler voert vervolgens ook de oefening in\ntegengestelde richting uit.\n1. Hielaanslag (Stap 2)\nOpgelet!\nDit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler stap 2 van de hielaanslag beheerst.\nMaterialen\nAantal spelers: 10\nAantal ballen: 2\nAantal pylonen: 4\nOrganisatie:\nDe spelers( 3 aan de ene en 2 aan de andere\nkant) staan verdeeld in 2 rijen achter de op een\nonderlinge afstand van 15 mtr. geplaatste\npylonen tegenover elkaar.De voorste speler\nheeft een bal in de handen en start de oefening\nWinnaar is de rij die het eerst de oefening\nuitgevoerd heeft\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.3 E: INGOOIEN, AANNEMEN-OPENEN, TOT 180º IN LIJNVORM", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 1 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 pakt de bal op, etc.\nD. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\n- Idem, andersom maar nu oefening met links uitvoeren.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler. Speler 3 start met dezelfde\noefening maar dan aan de andere kant.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.6: COMBINATIEOEFENING (1)", "content": "A. Speler 1 speelt naar speler 2.\n- Vanuit het midden gooit speler 1 de bal, onderhands, op het\nhoofd van de inlopende speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 kopt de bal, met een één/ tweebenige afzet, recht door\nnaar speler 3.\nC. Speler 3 dribbelt naar speler 4\n- Speler 3 controleert de bal en dribbelt naar speler 4 bij de\nvolgende pylon, etc.\nVariatie in uitvoering:\nIdem in tegengestelde richting.\nMaterialen\nAantal spelers: 4-6\nAantal ballen: 3-4\nAantal pylonen: 3\nOnderlinge afstand pylonen:\n2e jaars E-pupillen: 2 m\nD-,C-,B-,A-junioren: 3 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npositie.\nAanwijzingen\n- Vroegtijdig afzetten.\n- Afzetbeen terugbrengen in spanboog.\n- Zwaaibeen blijft gebogen voor-hoog.\n- Bal moet op het hoogste punt van de\nsprong worden gekopt (dode punt).\n- Juiste moment bovenlichaam naar voren en\narmen naar achter.\n- Bal raken met het voorhoofd.\n- De bal goed richting geven, door de\nduwbeweging in de richting van speler 3 te\nmaken.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O12', 20, '{"session_a": [{"type": "warming_up", "title": "NUMMER PASSSPEL", "content": "De spelers vormen een groepje van 5 spelers. Elke speler krijgt een nummer van\n1 t/m 5. De spelers lopen door elkaar in het vierkant en spelen elkaar\nnummergewijs ( 1 speelt naar 2; 2 speelt naar 3 etc.) de bal toe.\nOpgelet!\nGebruik het hele vak\nVariatie:\n- Laat de spelers kennis maken met verschillende afstanden.\n- Gebruik ook het andere been\nMaterialen\nTijd: 10-15 min\nPylonen: 4 pylonen om het speelveld uit te zetten\nBallen: voor een vijftal 1 bal"}, {"type": "techniek", "title": "A. EEN-TWEE OF TECHNIEK; TEGENSTANDER NAAST JE", "content": "Techniek uitvoeren met een tegenstander naast je.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander naast je te passeren.\n- Een 1 : 2 aangaan om een tegenstander naast je voorbij te gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nnaast je.\nUit te voeren technieken:\n- De Verandering (Stap 5)\n- De Overstap (Stap 6)\nA. Speler 1 speelt de bal op speler 2\nB. Speler 2 dribbelt de bal naar de middelste pylon en speler 3\nloopt hierbij mee.\nC. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 1 of hij passeert speler 3 met één van bovenstaande\ntechnieken.\nD. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nE. Speler 2 dribbelt over de achterlijn.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken De verandering (Stap\n5) en De Overstap (Stap 6).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 3.\nSpeler 3 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1 en\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger (speler 3) mag het hele vak\ngebruiken om te verdedigen.\n- Speler 1 mag de bal alleen vragen op de\nzijlijn."}, {"type": "techniek", "title": "B. EEN-TWEE OF TECHNIEK; TEGENSTANDER NAAST JE", "content": "Techniek uitvoeren met een tegenstander naast je.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander naast je te passeren.\n- Een 1 : 2 aangaan om een tegenstander naast je voorbij te gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nnaast je.\nUit te voeren technieken:\n- Kappen achter het standbeen (Stap 4)\n- Kappen binnenkant voet (Stap 5)\n- Kappen buitenkant voet (Stap 5)\nA. Speler 1 speelt de bal op speler 2\nB. Speler 2 dribbelt de bal naar de middelste pylon en speler 3\nloopt hierbij mee.\nC. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 1 of hij passeert speler 3 met één van bovenstaande\ntechnieken.\nD. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nE. Speler 2 dribbelt over de achterlijn.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Kappen binnenkant\nvoet (Stap 5), Kappen buitenkant voet (Stap 5) en Kappen achter\nstandbeen (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 3.\nSpeler 3 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1 en\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger (speler 3) mag het hele vak\ngebruiken om te verdedigen.\n- Speler 1 mag de bal alleen vragen op de\nzijlijn."}, {"type": "techniek", "title": "3. (5 : 2 + 3)", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de 2 verdedigers de bal kunnen veroveren.\nWanneer de verdedigers de bal onderscheppen dan moeten zij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 2 verdedigers en 2 aanvallers mee naar het andere\nveld. Nu moeten de vijf verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de 2 aanvallers de bal\nkunnen veroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (15m bij 12m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "RUIMTE VOETBAL 7 TEGEN 7", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen op een groot veld (ca. half voetbalveld).\nBeide teams verdedigen één kant van het veld, met daarop 2\ngrote poorten (min. 8 m. breed), die ca. 8 m. vanaf de achterlijn\nstaan.\nHet team in balbezit kan scoren door, zonder tussenkomst van de\ntegenstander, de bal naar elkaar over te spelen en daarna te\nscoren in één van de 2 poorten aan de lange zijde van de\ntegenstander..\nOpgelet:\n- men houdt balbezit na het score\n- er kan van beide kanten door de poorten worden gescoord.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "UIT DE RUG", "content": "Oefeningen, waarbij de spelers voor elkaar staan. De voorste speler staat hierbij\nin een vak van 2 bij 3 meter.\nDe achterste speler probeert, door plotseling te versnellen, uit de rug van de\nvoorste speler te komen en zonder getikt te worden de finishlijn te behalen.\nOpgelet!\nHet is een reactiespel, waarbij de jongste jeugd spelenderwijs het spel wordt\naangeleerd.\nLater, bij de oudere jeugd, kan daar goed gebruik van worden gemaakt.\nMaterialen\nAantal spelers: 2\nAantal pylonen: 6\nAantal ballen: 0\nOrganisatie:\nDe spelers staan voor elkaar. Bij deze oefening ligt het initiatief ligt bij de\nachterste speler."}, {"type": "techniek", "title": "STAP 2.5 E: AANNEMEN-OPENEN, TOT 180º IN LIJNVORM, WREEFTRAP", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 1 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de wreef van de rechtervoet.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\n- Idem, andersom maar nu oefening met links uitvoeren.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 20 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler. Speler 3 start met dezelfde\noefening maar dan aan de andere kant.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet.\nWreeftrap:\n- Strak inspelen met gevoel.\n- Spanning in de voet, enkel strekken en\nspannen.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- Bal in het hart raken."}, {"type": "techniek", "title": "OEFENVORM 1", "content": "De spelers staan bij de aangegeven onderdelen opgesteld\nA. Speler 1 speelt de bal met de binnenkant van de rechtervoet op\nde voorwaarts aanbiedende speler 2 en loopt daarna eerst door\nom de bal terug te krijgen en daarna biedt hij zich aan bij de 2e\npaal.\nB. Speler 2 speelt de bal direct weer met de binnenkant van de\nrechtervoet op de aanbiedende speler 1 en loopt daarna richting\n1e paal om zich aan te bieden.\nC. Intussen biedt speler 3 zich inzakkend aan en kiest daarbij het\njuiste moment van diepgaan om de bal in de loop aangespeeld te\nkrijgen van speler 1.\nD. Vervolgens ontvangt/controleert speler 3 de bal en geeft hem\nvoor op de, bij de eerste en tweede paal, ingelopen spelers 1 en 2.\nE. Daarna rond één van beide spelers de bal af op het doel.\nVariatie in uitvoering:\nWisselen van kant; wisselen van kant is wisselen van speelbeen.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nDoel: 1 (7.32m bij 2.44m)\nAantal pylonen: 4\nDoordraaien:\n- Speler 1 sluit achter in de rij van speler 2 aan.\n- Speler 2 sluit achter in de rij van speler 1 aan.\n- Spelers 3 en 6 geven om beurten de voorzet.\nAanwijzingen\n- Bij het 1e paal lopen moet je zorgen voor de\nkeeper uit te komen, op het moment dat de\nvoorzet komt.Loop vooral NIET voorbij de 1e\npaal!\n- Bij het 2e paal lopen moet je zorgen om\nschuin achter de speler bij de 1e paal te\nkomen, om daar de bal op te kunnen pakken,\ndie achter deze speler, ter hoogte van de 2e\npaal, komt.\n- Laat een voorzet van het doel afdraaien.\n- Speler in beweging, bal in beweging en de\nbal met een boodschap geven.\nNIET IN HET WATER 7 TEGEN 7\nMethodiek\nDeze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen.\nIn het veld staan 2 doelen met de achterkanten naar elkaar toe.\nTussen de doelen is een vak (water), waar geen spelers mogen\nkomen. De bal mg wel door het vak gespeeld worden.\nHet team dat scoort in het doel van de tegenstander krijgt 1 punt.\nOpgelet:\n- als een speler door het water loopt, krijgt de tegenstander een\nvrije bal op de achterlijn, aan de kant van het doel waar zij\nmoeten scoren.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 8\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O12', 21, '{"session_a": [{"type": "warming_up", "title": "PAALTJES VOETBAL 1", "content": "Het spel wordt gespeeld met 1 bal en elke speler start met 3\npunten. Alle spelers krijgen ergens in het vak een pylon te\nverdedigen. De spelers moeten proberen de pylon van elkaar\nomver te schieten. Gebeurt dit dan gaat er bij de desbetreffende\nspeler een punt af . Uiteindelijk blijft er 1 speler, de winnaar, over.\nVariatie:\nEen tweede bal in het spel brengen.\nOpgelet!\nBlijf niet voor je pylon hangen!\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nPylon: voor iedere speler 1\nBallen: 1-2\nAanwijzingen\nAls een speler geen punten meer heeft dan\ngaat hij aan de kant staan.\nSTAP 2.8 C: KAATSEN HOOG (MET BINNENKANT VOET) TOT 90º\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet in de handen van speler 3, etc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- Open draaien, naar de speelrichting.\n- De bal met de juiste snelheid/richting door\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "(6 : 4) OEFENING 2", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\n(Positiespel systeem Ajax)\nBij balverlies direct omschakelen. De middelste 4 nemen de\nposities over aan de zijkanten en het positiespel gaat gewoon\nverder.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 20m bij 15m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "BELGISCH VOETBAL 6 TEGEN 6 + 2 KEEPERS", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 6 spelers en 1\nkeeper, die tegen elkaar spelen.\nElk team verdedigt één doel. De doelen staan in het midden van\nhet veld met de achterkanten tegen elkaar.\nAls je scoort in het doel van de tegenstander krijg je een punt.\nVariatie:\n- als een team een goede hoge bal kan spelen, evt.toevoegen dat\nde bal niet hoog gepeeld mag worden, of omgekeerd als ze het\nniet kunnen.\nMaterialen\nAantal spelers: 12 + 2 Keepers\nAantal ballen: 5\nAantal pylonen: 4\nDoel: 2\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "TENNISBALLENSPEL", "content": "Bij deze oefening wordt het ‘omschakelmoment’ van een speler\naangeleerd en getraind. Door deze oefening wordt een speler\nhandig in het lichtvoetig draaien. Tevens benadrukt deze oefening\nhet ‘laag zitten’ bij het wegdraaien bij de speler.\nOrganisatieuitleg:\nEr zijn bij het spel 4 pylonnen, 4 tennisballen en één hoepel\naanwezig. De pylonnen staan in een plusvorm en op de pylonnen\nliggen de tennisballen.\nSpeluitleg:\nDe speler begint in de hoepel, op een commando van de trainer\nstart de speler naar de eerste pylon. De speler pakt de tennisbal\nmet de rechterhand en geeft de bal over in zijn linkerhand en legt\nhem vervolgens in de hoepel. Vanuit de hoepel vertrekt de zelfde\nspeler naar de tweede pylon en pakt tevens weer een tennisbal\nvan de tweede pylon met zijn rechterhand, geeft deze weer over\nnaar zijn linkerhand en legt vervolgens de tennisbal weer in de\nhoepel. De speler vervolgt de zelfde volgorde ook bij de derde en\nvierde pylon.\nDifferentiatie:\nBiedt de vorm ook aan in een wedstrijdvorm, zodat de oefening\nook op maximale snelheid uitgevoerd moet worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal organisaties:\nZoveel als mogelijk.\nAantal pylonnen voor één organisatie: 4\npylonnen.\nAantal hoepels voor één organisatie:\n1 hoepel\nOrganisatie:\nPer situatie voert één speler de oefening uit.\nAanwijzingen\nLet op!\nZorg ervoor dat de oefening volledig wordt\nuitgevoerd. Dat de speler tevens bij elke\nomschakeling ‘laag zit’ (gebogen knieën\nheeft)."}, {"type": "techniek", "title": "EEN-TWEE OF TECHNIEK; TEGENSTANDER VANAF DE ZIJKANT", "content": "Techniek uitvoeren met een tegenstander vanaf de zijkant.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander vanaf de zijkant te\npasseren.\n- Een 1 : 2 aangaan om een tegenstander vanaf de zijkant voorbij\nte gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nvanaf de zijkant.\nUit te voeren technieken:\n- 2x Kappen buitenkant voet (Stap 5)\n- Pirouette (Stap 7)\n- Aai kappen achter het standbeen(Stap 6)\n- De Schijntrap (Stap 6)\nA. Speler 1 speelt de bal op speler 2\nB. Speler 2 dribbelt de bal naar de middelste pylon en speler 3\nkomt vanaf de zijkant aanlopen.\nC. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 1 of hij passeert speler 3 met één van bovenstaande\ntechnieken.\nD. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nE. Speler 2 dribbelt over de achterlijn.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 5: Het oefenen van de technieken Aai kappen achter\nstandbeen (Stap 6), Kappen buitenkant voet (Stap 5), Pirouette\n(Stap 7) en De schijntrap (Stap 6).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 3.\nSpeler 3 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1 en\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger (speler 3) mag het hele vak\ngebruiken om te verdedigen.\n- Speler 1 mag de bal alleen vragen op de\nachterlijn."}, {"type": "techniek", "title": "AANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (6 : 5+KEEPER)", "content": "D.w.z. dat de 6 aanvallers/ middenvelder d.m.v. samenwerken\nkansen creëren.\nDe 5 verdedigers /middenvelders+ keeper kunnen hierbij scoren\ndoor de bal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 11+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 30m bij 35m\nD-pupillen: 35m bij 40m\nC-,B-,A-junioren: 40m bij 45m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O12', 22, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER ACHTER JE: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de voet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan (deze doet alsof hij een speler in de rug heeft).\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Binnen-buitenkant wegdraai (Stap 4)\n- Kappen buitenkant voet (Stap 4A)\n- De Overstap (Stap 5A)\nC. Speler 1 dribbelt naar speler 3\n- Speler 1 dribbelt de bal met de buitenkant van de linkervoet\nnaar speler 3.\n- Speler 1 geeft de bal aan speler 3, etc.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt, na de pass op speler 2, diens\nplaats in. Speler 2 dribbelt naar de plek ter\nhoogte van de overstaande pylonen en geeft\ndaar de bal aan speler 3. Deze speler start de\noefening opnieuw, maar nu in tegengestelde\nrichting, door de bal op de doorgelopen speler 1\nte spelen, etc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.6 E: KAATSEN-OPENEN, TOT 180º IN LIJNVORM, WREEFTRAP", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 kaatst de bal met de binnenkant van de rechtervoet\nterug.\nC. Speler 1 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal direct met de wreef van de rechtervoet\nnaar speler 3.\n- Speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nD. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\n- Idem, andersom maar nu oefening met links uitvoeren.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 20 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten.\nWreeftrap:\n- Strak inspelen met gevoel.\n- Spanning in de voet, enkel strekken en\nspannen.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- Bal in het hart raken."}, {"type": "techniek", "title": "3. (5 : 2 + 3)", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de 2 verdedigers de bal kunnen veroveren.\nWanneer de verdedigers de bal onderscheppen dan moeten zij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 2 verdedigers en 2 aanvallers mee naar het andere\nveld. Nu moeten de vijf verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de 2 aanvallers de bal\nkunnen veroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (15m bij 12m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "KANTELEN VOETBAL 7 TEGEN 7", "content": "Deze oefening wordt uitgevoerd met 2 teams van elk 7 spelers,\nwaarbij van elk team 1 speler in één van de 2 vierkanten staat.\nHet team in balbezit kan scoren door hun speler in het vierkant\naan te spelen, die vervolgens de bal doorspeelt naar een 3e\nspeler van het team.\nNa elke score draaien de spelers door en komt er een andere\nspeler in het vierkant te staan.\nHet balbezittende team behoudt na een score balbezit, maar de\nbal moet wel eerst weer worden teruggespeeld naar de eigen\nhelft, voordat er opnieuw gescoord kan worden.\nVariatie:\n- in plaats van de derde speler aan te spelen, mag de speler in het\nvierkant zelf met de bal het vierkant uitlopen.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 22\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP (3)", "content": "Is een oefening, waarbij de voorwaartse en zijwaartse vormen\ngecombineerd worden en aangeleerd over de stokken. De\noefening is opgebouwd van grove motoriek naar de fijne motoriek.\nDat wil zeggen binnen de looptraining, er wordt gewerkt van een\nskipping naar skipping 45 graden en vervolgens naar kort\nvoetenwerk.\nEr moet hierbij wel nadrukkelijk worden gelet op het lichtvoetig\nagreren over de stokken. Dat wil zeggen dat alles met de bal van\nde voet wordt uitgevoerd. Ten allen tijden wordt er op de bal van\nde voet gelopen.\nStap 1: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt voorwaarts genomen en vervolgens wordt er met twee\nvoeten teruggestapt, de derde stok wordt zijwaarts genomen en\nde vijfde stok vervolgens weer voorwaarts. De tussen stokken\nworden gelopen met één voet tussen de stokken.\nStap 2: Er wordt met de linkervoet begonnen. De eerste stok\nwordt voorwaarts genomen en vervolgens wordt er met twee\nvoeten teruggestapt, de derde stok wordt zijwaarts genomen en\nde vijfde stok vervolgens weer voorwaarts. De tussen stokken\nworden gelopen met één voet tussen de stokken.\nStap 3: Er wordt met de linkervoet begonnen. De eerste stok\nwordt zijwaarts genomen en vervolgens wordt er met twee voeten\nteruggestapt, de derde stok wordt voorwaarts genomen en de\nvijfde stok vervolgens weer zijwaarts. De tussen stokken worden\ngelopen met één voet tussen de stokken.\nStap 4: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt zijwaarts genomen en vervolgens wordt er met twee voeten\nteruggestapt, de derde stok wordt voorwaarts genomen en de\nvijfde stok vervolgens weer zijwaarts. De tussen stokken worden\ngelopen met één voet tussen de stokken.\nDifferentiatie:\nDe beweging wordt aan beide kanten uitgevoerd. Dat wil zeggen\ndat de zijwaarts rechts en links uitgevoerd moeten worden.\nLet op!\nDe romphouding moet ten allen tijden recht zijn en er moet een\narminzet aanwezig zijn.\nMaterialen\nAantal spelers: het gehele team.\nAantal stokkenparcours:\nEén, bij voorkeur twee.\nAantal pylonnen:\n12\nAantal stokken:\n5\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "C. EEN-TWEE OF TECHNIEK; BINNENKANT ANDERE VOET, VOOR JE (1)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de binnenkant van de andere voet.\nUit te voeren technieken:\n- Uitstappen meenemen (Stap 6)\n- Akka (binnen-buiten) (Stap 4)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de binnenkant van de\nlinkervoet richting speler 1\nE. Speler 2 (doet alsof hij een 1 : 2 wil aangaan met speler 3)\nvoert daar één van onderstaande bewegingen uit:\n- Uitstappen meenemen (Stap 6)\n- Akka (binnen-buiten) (Stap 4)\nF. Speler 2 versnelt kort met de bal aan buitenkant linkervoet tot\naan de buitenste pylonen\nG. Speler 2 dribbelt rustig terug naar het beginpunt.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 3: Het oefenen van de technieken Uitstappen meenemen\n(Stap 6) en Akka (binnen-buiten) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 2\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan er start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "TEGENSTANDER VOOR JE: MET WEERSTAND (2)", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\nDribbelen buitenkant voet:\n- Schaar (Stap 5B)\nA. Speler 1 start de oefening door de bal met de rechtervoet naar\nde middelste pylonen te dribbelen.\nB. Ter hoogte daarvan komt een tegenstander (speler 2) frontaal\nop hem inlopen. Hij passeert vervolgens de tegenstander met één\nvan de bovengenoemde technieken.\nC. Daarna controleert hij de bal en rond vervolgens af op het doel\nD. Speler 2 haalt de bal en sluit achter in de andere rij aan en\nspeler 1 neemt de taak over van speler 2.\nOpgelet!\nDe spelers 5,6,7 en 8 voeren dezelfde oefening uit op het andere\ndoel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 2 haalt de bal en sluit achter in de\nandere rij aan.\n- Speler 1 neemt de taak over van speler 2.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O12', 23, '{"session_a": [{"type": "warming_up", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º IN X-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- speler 2 biedt zich \"voorwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\n- dem, andersom oefening met links uitvoeren.\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 5\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "A. EEN-TWEE OF TECHNIEK; BUITENKANT VOET, VOOR JE (2)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de buitenkant van de voet.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de buitenkant van de voet.\n- Een 1 : 2 aangaan met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de buitenkant van de voet.\n- Een keuze maken om een 1 : 2 aan te gaan of één van de\naangegeven technieken uit te voeren, waarbij je aan komt\ndribbelen met de bal aan de buitenkant van de voet.\nUit te voeren technieken:\n- Akka (buitenkant-binnen) (Stap 4)\n- Schaar (Stap 6)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de buitenkant van de\nrechtervoet richting speler 1\nE. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 3 of hij passeert hem met één van bovenstaande\ntechnieken\nF. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nG. Speler 2 speelt de bal op speler 3.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 3: Het oefenen van de technieken Schaar (Stap 6) en\nAkka (buiten-binnen) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan, krijgt de bal van speler 2 er\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "3. (6 : 3)", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 3\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 9\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 7:7", "content": "Zeven aanvallers moeten d.m.v. samenspel/ individuele actie 7\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij\nopnieuw.opnieuw.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nE-pupillen: 35m bij 40m\nD-pupillen: 40m bij 45m\nC-junioren: 45m bij 50m\nB-,A-junioren: 50m bij 55m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een 3-1-3 formatie.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering."}], "session_b": [{"type": "warming_up", "title": "REACTIE-ACTIE", "content": "Dit is een oefening voor het hele team. Het hele team zit/ ligt hierbij op de\nachterlijn van het 16-metergebied. Op een teken van de trainer (b.v. “JA”) staan\nde spelers op en versnellen naar de overkant.\nDifferentiatie:\n- varieer in de uitgangshouding, zoals zitten op de billen, liggen op de buik, -\nzijde (beide kanten) of op de rug.\nWees daarbij creatief!\nOpgelet!\n- dit zijn introductievormen bij de looptraining.\nMaterialen\nAantal spelers: gehele team.\nOrganisatie:\nAchterlijn 16-meter gebied."}, {"type": "techniek", "title": "STAP 2.3 E: INGOOIEN, AANNEMEN-OPENEN, TOT 180º IN LIJNVORM", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 1 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 3 pakt de bal op, etc.\nD. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\n- Idem, andersom maar nu oefening met links uitvoeren.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler. Speler 3 start met dezelfde\noefening maar dan aan de andere kant.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "STAP 2.6: COMBINATIEOEFENING (2)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 1 gooit de bal onderhands op het hoofd van de inlopende\nspeler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 kopt de bal, met een één/ tweebenige afzet, schuin door\nnaar speler 3.\nC. Speler 3 dribbelt naar speler 4\n- Speler 3 controleert de bal en dribbelt naar speler 4 bij de\nvolgende pylon, etc.\nVariatie in uitvoering:\nIdem in tegengestelde richting.\nMaterialen\nAantal spelers: 4-8\nAantal ballen: 2-4\nAantal pylonen: 3\nOnderlinge afstand pylonen:\n2e jaars E-pupillen: 2 m\nD-,C-,B-,A-junioren: 3 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npositie.\nAanwijzingen\n- Vroegtijdig afzetten.\n- Afzetbeen terugbrengen in spanboog.\n- Zwaaibeen blijft gebogen voor-hoog.\n- Bal moet op het hoogste punt van de\nsprong worden gekopt (dode punt).\n- Juiste moment bovenlichaam naar voren en\narmen naar achter.\n- Bal raken met het voorhoofd.\n- De bal goed richting geven, door de\nduwbeweging in de richting van speler 3 te\nmaken.\nLIJNDRIBBEL 3:2 MET DOEL\nMethodiek\nd.w.z. dat 3 aanvallers d.m.v. samenspel/ een persoonlijke actie 2\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 3 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger. (alleen\nvan toepassing voor teams 11-11)\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 5\nAantal pylonen: 4\nAantal ballen: 3\nAfstand tussen de pylonen:\nF-pupillen: 18m bij 12m\nE-pupillen: 20m bij 15m\nD-pupillen: 25m bij 20m\nC-,B-,A-junioren: 30m bij 25m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het breed houden van het veld door de\naanvallers\n- diepte brengen in het spel, rekening\nhoudend met buitenspel, maar ook met het\ntijdig omschakelen bij balverlies\n- de positie van de middelste man die als\nverbindingsspeler optreedt en daarbij ook op\nhet juiste moment de actie kan/moet maken.\nVerdedigers coachen op:\n- het goed knijpen, daar waar dit wordt\ngevraagd\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O12', 24, '{"session_a": [{"type": "warming_up", "title": "STAP 2.1 E: AANBIEDEN, TOT 180º IN LIJN/STROOMVORM", "content": "A. Speler 1 speelt naar spelers 2.\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinkervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nlinkervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: 4-5\nAantal ballen: 1\nAantal pylonen: 9\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "B. EEN-TWEE OF TECHNIEK; BINNENKANT VOET, VOOR JE (2)", "content": "Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de binnenkant van de voet.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de binnenkant van de voet.\n- Een 1 : 2 aangaan met een tegenstander voor je, waarbij je aan\nkomt dribbelen met de bal aan de binnenkant van de voet.\n- Een keuze maken om een 1 : 2 aan te gaan of één van de\naangegeven technieken uit te voeren, waarbij je aan komt\ndribbelen met de bal aan de binnenkant van de voet.\nUit te voeren technieken:\n- Aai buitenkant voet (Stap 6)\n- Sleep (Stap 5)\n- Akka (binnen-voor) (Stap 4)\nA. Speler 1 speelt de bal op de openstaande speler 2\nB. Speler 2 dribbelt de bal tot aan de eerste pylonen\nC. Speler 2 kapt daar de bal af\nD. Speler 2 dribbelt vervolgens de bal met de binnenkant van de\nrechtervoet richting speler 1\nE. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 3 of hij passeert hem met één van bovenstaande\ntechnieken\nF. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nG. Speler 2 speelt de bal op speler 3.\nH. Speler 3 start de oefening opnieuw, maar nu vanaf de andere\nkant.\nVariatie\nVariatie 4: Het oefenen van de technieken Aai buitenkant voet\n(Stap 6), Sleep (Stap 5) en Akka (binnen-voor) (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 4\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1.\nSpeler 3 blijft staan, krijgt de bal van speler 2 er\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger verdedigt vanaf de lijn een\npaar meter naar voren."}, {"type": "techniek", "title": "(6 : 4) OEFENING 1", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\n(Positiespel systeem Ajax)\nWisselen van taak na een aantal minuten (alleen de nummers 4\nen 10 blijven staan) / of na een aantal keer afpakken.\nWisselen van taak: De verdediger die het langst in het midden\nheeft gestaan wisselt met de aanvaller die de fout heeft gemaakt\nof hij wisselt met de langst staande aanvaller.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 20m bij 15m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "SKIPPING MET BAL", "content": "Is een oefening, waarbij de speler de stappen van de\nonderstaande techniek, op de plaats, uitvoert, terwijl hij een bal in\nbeide handen voor zich houdt.Bij elke stap van de skipping raakt\nde speler bij het heffen van zijn knie met zijn bovenbeen de bal.\n1. Skipping (Stap 3 en 4)\nOpgelet!\n- dit is een eindvorm. Deze vorm kan alleen worden uitgevoerd als\nde speler de stappen 3 en 4 van de skipping beheerst.\nDifferentiatie:\n- uitvoering in voorwaartse richting.\nMaterialen\nAantal spelers: gehele team.\nAantal ballen: aantal ballen aan aantal spelers\naanpassen.\nOrganisatie:\n- de spelers lopen van 5-meterlijn tot 16-\nmeterlijn in het 16-meter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek, zie\ntechnieklijst.\nSTAP 2.8 C: KAATSEN HOOG (MET BINNENKANT VOET) TOT 90º\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet in de handen van speler 3, etc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- Open draaien, naar de speelrichting.\n- De bal met de juiste snelheid/richting door\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "OEFENVORM 2", "content": "De spelers staan bij de aangegeven onderdelen opgesteld\nA. Speler 1 speelt de bal met de binnenkant van de rechtervoet op\nde voorwaarts aanbiedende speler 2 en loopt daarna door om de\nbal terug te krijgen.\nB. Speler 2 speelt de bal direct weer met de binnenkant van de\nrechtervoet op de aanbiedende speler 1 en loopt daarna richting\n1e paal om zich daar aan te bieden.\nC. Intussen biedt speler 3 zich inzakkend aan en kiest daarbij het\njuiste moment van diepgaan om de bal in de loop aangespeeld te\nkrijgen van speler 1.\nD. Vervolgens ontvangt/controleert speler 3 de bal en geeft hem\nvoor op de, bij de eerste en tweede paal, ingelopen spelers 2 en 4.\nE. Daarna rond één van beiden de bal af op doel.\nVariatie in uitvoering:\nWisselen van kant; wisselen van kant is wisselen van speelbeen.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nDoel: 1 (7.32m bij 2.44m)\nAantal pylonen: 4\nDoordraaien:\nMet de klok mee:\n- Speler 1 sluit achter in de rij van speler 4 aan.\n- Speler 2 sluit achter in de rij van speler 1 aan.\n- Speler 4 sluit achter in de rij van speler 2 aan.\n- Spelers 3 en 7 geven om beurten de voorzet.\nAanwijzingen\n- Bij het 1e paal lopen moet je zorgen voor de\nkeeper uit te komen, op het moment dat de\nvoorzet komt.Loop vooral NIET voorbij de 1e\npaal!\n- Bij het 2e paal lopen moet je zorgen om\nschuin achter de speler bij de 1e paal te\nkomen, om daar de bal op te kunnen pakken,\ndie achter deze speler, ter hoogte van de 2e\npaal, komt.\n- Laat een voorzet van het doel afdraaien.\n- Speler in beweging, bal in beweging en de\nbal met een boodschap geven."}, {"type": "partijvorm", "title": "PARTIJVORM 7:7 + 2 KEEPERS", "content": "Zeven aanvallers moeten d.m.v. samenspel/ individuele actie 7\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij\nopnieuw.opnieuw.\nMaterialen\nAantal spelers:14 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nE-pupillen: 40m bij 35m\nD-pupillen: 45m bij 40m\nC-junioren: 50m bij 45m\nB-,A-junioren: 55m bij 50m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een 1-3-1-3\nformatie.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O12', 25, '{"session_a": [{"type": "warming_up", "title": "JAGERBAL", "content": "Dit is een spel waarbij één speler de bal heeft en tevens de tikker is. Een andere\nspeler is de verlosser. De tikker probeert, met de bal, zoveel mogelijk spelers af\nte tikken.\nNadat een speler is afgetikt gaat hij met gespreide benen staan. De verlosser kan\neen speler verlossen door onder zijn poortje door te kruipen. Wie kan alle spelers\naftikken?\nVariatie:\nMeerdere tikkers of geheime tikkers aanwijzen.\nOpgelet!\nNadat een verlosser je heeft “vrijgemaakt\", kun je weer aan het spel deelnemen.\nMaterialen\nDuur:10-15 min\nDuur ronde: 1 a 2 min\nAantal: 6-12 spelers\nPylonen: 4 om het speelveld af te bakenen."}, {"type": "techniek", "title": "STAP 2.5 E: AANNEMEN-OPENEN, TOT 180º IN DIAMANTVORM (1)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet\nlangs speler 3 naar speler 2.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 speelt naar speler 4.\n- Idem als beschreven bij A, etc.\nD. Speler 4 speelt naar speler 5.\n- Idem als beschreven bij B, etc.\nE. Speler 5 speelt naar speler 6.\n- Speler 6 biedt zich \"naar links\" aan.\n- Speler 5 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 6 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nF. Speler 6 dribbelt met de bal naar speler 7.\n- Speler 6 sluit achter speler 7 aan.\nG. Speler 7 start oefening op het moment dat de bal bij speler 5 is.\nVariatie in uitvoering:\n- Idem, andersom maar nu oefening met links uitvoeren.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 6\nAantal pylonen: 6\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "(6 : 4) OEFENING 2", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\n(Positiespel systeem Ajax)\nBij balverlies direct omschakelen. De middelste 4 nemen de\nposities over aan de zijkanten en het positiespel gaat gewoon\nverder.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 20m bij 15m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 7:7 + 2 KEEPERS", "content": "Zeven aanvallers moeten d.m.v. samenspel/ individuele actie 7\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij\nopnieuw.opnieuw.\nMaterialen\nAantal spelers:14 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nE-pupillen: 40m bij 35m\nD-pupillen: 45m bij 40m\nC-junioren: 50m bij 45m\nB-,A-junioren: 55m bij 50m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een 1-3-1-3\nformatie.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "RATTEN EN RAVEN MET BAL", "content": "Het spel wordt gespeeld met tweetallen, die recht tegenover\nelkaar staan op een onderlinge afstand van 2 meter. Elke speler\nheeft een bal.\nAan de ene kant staan de ratten en aan andere kant de raven.\nAls verteller vertelt de trainer een verhaal waarin de woorden\nratten en raven steeds voorkomen. Op het moment dat de trainer\neen van deze namen noemt, dan moet die groep zo snel mogelijk\nnaar hun achterlijn zien te lopen.De andere groep moet hen zien\nte tikken voordat zij bij hun achterlijn zijn.\nJe krijgt voor elke getikte speler 1 punt.\nMaterialen\nDuur:10-15 min\nAantal: 4 of meer spelers\nVoor iedere speler een bal\nPylonen:\n- 4 om het speelveld af te bakenen.\n- 4 pylonen/hoedjes om de vrije zone aan te\ngeven.\n- 4 pylonen/hoedjes om de startlijn aan te geven.\n- 2 pylonen/hoedjes op de middenlijn aan te\ngeven\nAanwijzingen\n- zorg dat de spelers ook echt starten\nwanneer hun naam genoemd wordt\n- probeer een leuk verhaal van te maken.\nNiet alleen maar ratten en raven roepen.\nSTAP 2.7 C: AANNEMEN (MET HET HOOFD) EN SPELEN TOT 90º\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op hoofdhoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 neemt de bal met het voorhoofd aan en speelt de bal\ndirect door met de binnenkant van de rechtervoet naar speler 3,\netc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\n2e jaars E-pupillen: 4 m\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAannemen:\n- Open aannemen, in de speelrichting.\n- Bij het aannemen met het hoofd soepel en\nflexibel met de bal meegaan en zodoende bal\n\"dood\" maken.\n- Bal moet voor je liggen, maar binnen bereik\n- Snelheid houden na de aanname voor de\nvolgende actie.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "VERDEDIGEN DOOR AANVALLERS EN MIDDENVELDERS (5 : 6+KEEPER)", "content": "D.w.z. dat 5 aanvallers/ middenvelders door samen te werken in\nbalbezit moeten zien te komen. Daarbij moeten zij ook zo goed\nmogelijk positioneel blijven verdedigen.\nDe verdedigende partij (6 verdedigers /middenvelders+ Keeper)\nkan scoren door de bal over de lijn van één van de doeltjes te\ndribbelen.\nBal afgepakt dan kunnen de aanvallers op het grote doel scoren.\nDe opbouw start altijd bij de doelman\nMaterialen\nAantal spelers: 11+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 30m bij 35m\nD-pupillen: 35m bij 40m\nC-,B-,A-junioren: 40m bij 45m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij verdedigen\ncoachen op:\n- het knijpen en kantelen naar de kant waar\nde bal is\n- het coachen van elkaar (het initiatief ligt bij\nde achterste middenvelder)\n- het dekken vanuit de zone, vanwege de\novertalsituatie.\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het breed maken van het veld.\n- het zoeken van de kortste weg naar het\ndoel om tot scoren te komen."}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O12', 26, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VANAF DE ZIJKANT: IN EEN RECHTHOEKVORM", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- 2x kappen buitenkant voet (Stap 4A)\n- Pirouette (Stap 6A)\n- Aai-kappen achter het standbeen (Stap 5A)\n- de Schijntrap (Stap 5A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan en voert nu, met het andere been, in tegengestelde richting\ndezelfde oefening uit.\n- Speler 2 geeft de bal aan speler 3, etc.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 3-5\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 passed de bal op speler 2. Deze speler\nvoert de oefening in de tegenovergestelde\nrichting met het andere been uit en passed de\nbal op speler 3. Enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.6 E: KAATSEN-OPENEN, TOT 180º IN DIAMANTVORM (1)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet\nlangs speler 3 naar speler 2.\nB. Speler 2 speelt naar speler 3.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 speelt naar speler 4.\n- Speler 5 biedt zich \"voorwaarts\" aan.\n- Speler 4 biedt zich \"naar links\" aan.\n- Speler 3 speelt de bal direct met de binnenkant van de\nrechtervoet langs speler 5 naar speler 4.\nD. Speler 4 speelt naar speler 5.\n- Speler 5 biedt zich \"naar rechts\" aan.\n- Speler 4 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 5.\nE. Speler 5 speelt naar speler 6.\n- Speler 6 biedt zich \"naar links\" aan.\n- Speler 5 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 6.\nSpeler 6 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nF. Speler 6 dribbelt met de bal naar speler 7.\n- Speler 6 sluit achter speler 7 aan.\nG. Speler 7 start oefening op het moment dat de bal bij speler 5 is.\nVariatie in uitvoering:\nIdem, andersom maar nu oefening met links uitvoeren.\nMaterialen\nAantal spelers: 7-12\nAantal ballen: 2-5\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "3. (6 : 3)", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 3\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 9\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "HOEK VOETBAL 7 TEGEN 7", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen op een groot vierkant veld, waarvan de\nhoeken gemarkeerd zijn met pylonen.\nIn de hoeken van het veld kan de partij in balbezit scoren. Alleen\nde balbezittende partij mag in deze hoeken komen.\nAls je gescoord hebt behoud je team balbezit en mag je proberen\nin één van de andere hoeken te scoren.\nLET OP:\nEr mag nooit 2x achter elkaar in dezelfde hoek gescoord worden\n(door beide teams niet).\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "DE OOIEVAAR", "content": "Is een oefening, waarbij de speler(s) de stap van één van de\nonderstaande technieken, op de plaats, moet(en)uitvoeren.\nBelangrijk hierbij is dat de speler na 5 skippings gedurende 5 tot\n10 seconden op zijn gehele voet stil blijft staan. Als de speler dit\nniet volhoud dan moet hij een sprint maken tot aan de 16-\nmeterlijn of tot bij de trainer.\n1. Skipping (Stap 3)\n2. Hielaanslag ( Stap 1)\nOpgelet!\nDit is een aanleervorm, waarbij de speler de stabiliteit in zijn been\n(knie/enkel), maar ook dat van zijn bovenlichaam (heup/borst)\nleert te beheersen.\nDifferentiatie:\n- Op de bal van de voet stilstaan\n- Uitvoering in voorwaartse richting.\n- Variëren in aantal skippings.\nMaterialen\nAantal spelers: gehele team\nOrganisatie:\nDe spelers staan kris kras door elkaar in het 16-\nmeter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "EEN-TWEE OF TECHNIEK; TEGENSTANDER ACHTER JE", "content": "Techniek uitvoeren met een tegenstander achter je.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander achter je te passeren.\n- Een 1 : 2 aangaan om een tegenstander achter je voorbij te gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nachter je\nUit te voeren technieken:\n- Kappen buitenkant voet (Stap 5)\n- Binnen-buitenkant wegdraai (Stap 6)\n- De Overstap (Stap 6)\nA. Speler 1 passed de bal naar speler 3 die een tegenstander\n(speler 4) in de rug heeft.\nB. Speler 1 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 2 of hij passeert speler 4 met één van bovenstaande\ntechnieken.\nC. Speler 3 dribbelt of loopt door om de bal te ontvangen.\nD. Speler 3 dribbelt over de achterlijn en start de oefening\nopnieuw vanaf de andere kant.\nVariatie\nVariatie 4: Het oefenen van de technieken De Overstap (Stap 6),\nKappen buitenkant voet (Stap 5) en Binnen buiten wegdraai (Stap\n6).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 4\nSpeler 4 neemt de taak over van speler 3.\nSpeler 3 blijft staan en start nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger mag het hele vak gebruiken\nom te verdedigen."}, {"type": "techniek", "title": "TEGENSTANDER ACHTER JE: MET WEERSTAND", "content": "Deze oefenvorm wordt uitgevoerd met één van de volgende\npasseerbewegingen:\n- Kappen buitenkant voet (Stap 4B)\n- De Overstap (Stap 5B)\n- Binnen-buitenkant wegdraai (Stap 5)\nA. Speler 1 start de oefening door de bal met de rechter\nbinnenkant van de voet op de aanbiedende speler 2 te\npassen(deze heeft een verdediger, speler 3,in de rug).\nB. Speler 2 ontvangt de bal en passeert vervolgens met één van\nde bovengenoemde technieken de in zijn rug staande verdediger.\nC. Daarna dribbelt hij richting doel om vervolgens hierop af te\nronden.\nD. Speler 3 haalt de bal en sluit achter in de andere rij aan.\nOpgelet!\nDe spelers 6,7,8,9 en 10 voeren dezelfde oefening uit op het\nandere doel.\nVariatie:\nIdem, maar nu de oefening met het andere been uitvoeren.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nAantal doelen: 2\nAantal pylonen: 8\nDoelen: 2\nE-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44m\nAfstand tussen de pylonen: 10 mtr.\nSchietafstand vanaf doel:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD- pupillen: 14 m\nC-,B-,A-junioren: >16 m\nDoordraaien:\n- Speler 1 loopt door naar de volgende pylon en\nneemt de positie over van speler 2.\n- Speler 2 neemt de taak over van speler 3.\n- Speler 3 haalt de bal en sluit achter in de\nandere rij aan.\n- Idem aan de andere kant.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\nAfwerken op doel:\n- Bal in het hart raken\n- Spanning in de voet\n- Raakvlak: Binnenkant of volle wreef,\nafhankelijk van de situatie.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- De overgang dribbelen naar schieten moet\nvloeiend verlopen."}, {"type": "partijvorm", "title": "PARTIJVORM 3:3 (2)", "content": "Drie aanvallers moeten d.m.v. samenspel/ individuele actie 3\nverdedigers uitspelen om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\nBal door buiten het veld, dan start het andere team de partij\nopnieuw.\nVariatie in uitvoering:\nDrie teams van 3 man en 3 keepers.\nHet scorende team behoud balbezit en start steeds vanaf hun\ndoelman.\nHet 3e team verzorgt de aanvoer van de ballen.\nBal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:6(9)+2(3) keepers\nAantal ballen: veel\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na drie minuten nog niet is gescoord, dan\nwordt de langst staande partij gewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden met omschakeling bij\nbalverlies en bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n-het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het gebruik maken van de buitenspelregel\n- het rekening houden met omschakeling bij\nbalverovering.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)\n- het eventueel wisselen van tegenstander na\n10 minuten.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}, {"type": "partijvorm", "title": "PARTIJVORM 4:4 (2)", "content": "Vier aanvallers moeten d.m.v. samenspel/ individuele actie 4\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\nBal buiten het veld, dan start het andere team de partij opnieuw.\nVariatie in uitvoering:\nMet 3 teams wisselen naar eigen inzicht.\nMaterialen\nAantal spelers:8(12)+2(3) keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 25m bij 20m\nE-pupillen: 30m bij 25m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nDoordraaien:\nHet winnende team blijft staan en het\nverliezende team wisselt met het 3e team.\nAls er na twee minuten nog niet is gescoord, dan\nwordt de partij die het langst in het veld staat\ngewisseld.\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gebruik gemaakt moet worden van\nde vrije positie van de keeper (overtalsituatie)\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers.\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler).\n- het rekening houden bij balverovering met\nomschakeling.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen bij het verdedigen van je\nmedespelers\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- accenten leggen op: individuele actie;\nscoren onder druk; snelle omschakeling;\n- in de organisatie aandacht voor: genoeg\nballen om het veld; strakke felle coaching"}]}'::jsonb),
('O12', 27, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (1)", "content": "De onderstaande stap van de volgende techniek dient naar eigen\ninzicht, rekening houdend met de beschikbare tijd, aangeleerd te\nworden.\nA. Speler 1 dribbelt richting middelste pylonen\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet.\nB. Speler 1 maakt de beweging\n- Schaar (Stap 5A)\n- Akka (buiten-binnen) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- Het moment waarop je de beweging inzet is\nafhankelijk van de snelheid van het dribbelen\n(eerder of later inzetten).\n- Je mag de tegenstander, bij de uitvoering\nvan de oefening, niet raken."}, {"type": "techniek", "title": "STAP 2.8 C: KAATSEN HOOG (MET BINNENKANT VOET) TOT 90º", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet in de handen van speler 3, etc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- Open draaien, naar de speelrichting.\n- De bal met de juiste snelheid/richting door\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "3. (5 : 2 + 3)", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de 2 verdedigers de bal kunnen veroveren.\nWanneer de verdedigers de bal onderscheppen dan moeten zij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 2 verdedigers en 2 aanvallers mee naar het andere\nveld. Nu moeten de vijf verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de 2 aanvallers de bal\nkunnen veroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (15m bij 12m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "TENNISBALLENSPEL", "content": "Bij deze oefening wordt het ‘omschakelmoment’ van een speler\naangeleerd en getraind. Door deze oefening wordt een speler\nhandig in het lichtvoetig draaien. Tevens benadrukt deze oefening\nhet ‘laag zitten’ bij het wegdraaien bij de speler.\nOrganisatieuitleg:\nEr zijn bij het spel 4 pylonnen, 4 tennisballen en één hoepel\naanwezig. De pylonnen staan in een plusvorm en op de pylonnen\nliggen de tennisballen.\nSpeluitleg:\nDe speler begint in de hoepel, op een commando van de trainer\nstart de speler naar de eerste pylon. De speler pakt de tennisbal\nmet de rechterhand en geeft de bal over in zijn linkerhand en legt\nhem vervolgens in de hoepel. Vanuit de hoepel vertrekt de zelfde\nspeler naar de tweede pylon en pakt tevens weer een tennisbal\nvan de tweede pylon met zijn rechterhand, geeft deze weer over\nnaar zijn linkerhand en legt vervolgens de tennisbal weer in de\nhoepel. De speler vervolgt de zelfde volgorde ook bij de derde en\nvierde pylon.\nDifferentiatie:\nBiedt de vorm ook aan in een wedstrijdvorm, zodat de oefening\nook op maximale snelheid uitgevoerd moet worden.\nMaterialen\nAantal spelers: het gehele team.\nAantal organisaties:\nZoveel als mogelijk.\nAantal pylonnen voor één organisatie: 4\npylonnen.\nAantal hoepels voor één organisatie:\n1 hoepel\nOrganisatie:\nPer situatie voert één speler de oefening uit.\nAanwijzingen\nLet op!\nZorg ervoor dat de oefening volledig wordt\nuitgevoerd. Dat de speler tevens bij elke\nomschakeling ‘laag zit’ (gebogen knieën\nheeft)."}, {"type": "techniek", "title": "STAP 2.3 E: INGOOIEN, AANNEMEN-OPENEN, TOT 180º IN LIJNVORM, WREEF", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 1 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de wreef van de rechtervoet.\n- Speler 3 pakt de bal op, etc.\nD. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\n- Idem, andersom maar nu oefening met links uitvoeren.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 20 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler. Speler 3 start met dezelfde\noefening maar dan aan de andere kant.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet.\nWreeftrap:\n- Strak inspelen met gevoel.\n- Spanning in de voet, enkel strekken en\nspannen.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- Bal in het hart raken."}, {"type": "techniek", "title": "STAP 2.6: COMBINATIEOEFENING (3)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 1 gooit de bal onderhands op het hoofd van de inlopende\nspeler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 kopt de bal, met een één/ tweebenige afzet, schuin naar\nspeler 3.\n- Speler 3 controleert de bal.\nC. Speler 3 speelt naar speler 2\n- Speler 3 speelt de bal, terug naar speler 2.\nD. Speler 2 speelt naar speler 3\n- Speler 2 kaatst naar speler 3\n- Speler 3 neemt de bal in de loop aan.\nE. Speler 2 dribbelt de bal\n- Speler 3 dribbelt naar speler 4 bij de volgende pylon, etc.\nVariatie in uitvoering:\nIdem in tegengestelde richting.\nMaterialen\nAantal spelers: 4-8\nAantal ballen: 2-4\nAantal pylonen: 3\nOnderlinge afstand pylonen:\n2e jaars E-pupillen: 2 m\nD-,C-,B-,A-junioren: 3 m\nDoordraaien:\nAchter de bal aan doorlopen naar de volgende\npositie.\nAanwijzingen\n- Vroegtijdig afzetten.\n- Afzetbeen terugbrengen in spanboog.\n- Zwaaibeen blijft gebogen voor-hoog.\n- Bal moet op het hoogste punt van de\nsprong worden gekopt (dode punt).\n- Juiste moment bovenlichaam naar voren en\narmen naar achter.\n- Bal raken met het voorhoofd.\n- De bal goed richting geven, door de\nduwbeweging in de richting van speler 3 te\nmaken.\nLIJNDRIBBEL 4:3 MET DOEL\nMethodiek\nd.w.z. dat 4 aanvallers d.m.v. samenspel/ een persoonlijke actie 3\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 4 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger (alleen van\ntoepassing voor teams 11-11).\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nD-pupillen: 30m bij 25m\nC-,B-,A-junioren: 35m bij 30m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gezorgd moet worden dat de\nnummer 3 de vrije man is\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers\nVerdedigers coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O12', 28, '{"session_a": [{"type": "warming_up", "title": "PAALTJES VOETBAL 2", "content": "Het spel wordt gespeeld met tweetallen, elk met 1 pylon en een\nbal. De ene speler is verdediger en de ander aanvaller. De\naanvaller moet proberen 1 punt te scoren door de pylon omver te\nschieten. De verdediger probeert dit te voorkomen.\nOpgelet!\n- Na een aantal minuten wisselen van functie.\n- De spelers moeten binnen het afgebakende veld blijven.\nVariatie:\nBij een score wisselen alle spelers tegelijk van functie\nMaterialen\nDuur:10-15 min\nAantal: 2 of meer spelers\nPylon: voor ieder tweetal 1\nBallen: 1-2\nAanwijzingen\nZorg dat de spelers niet voor de pylon blijven\nhangen."}, {"type": "techniek", "title": "A. EEN-TWEE OF TECHNIEK; TEGENSTANDER NAAST JE", "content": "Techniek uitvoeren met een tegenstander naast je.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander naast je te passeren.\n- Een 1 : 2 aangaan om een tegenstander naast je voorbij te gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nnaast je.\nUit te voeren technieken:\n- De Verandering (Stap 5)\n- De Overstap (Stap 6)\nA. Speler 1 speelt de bal op speler 2\nB. Speler 2 dribbelt de bal naar de middelste pylon en speler 3\nloopt hierbij mee.\nC. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 1 of hij passeert speler 3 met één van bovenstaande\ntechnieken.\nD. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nE. Speler 2 dribbelt over de achterlijn.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 3: Het oefenen van de technieken De verandering (Stap\n5) en De Overstap (Stap 6).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 3.\nSpeler 3 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1 en\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger (speler 3) mag het hele vak\ngebruiken om te verdedigen.\n- Speler 1 mag de bal alleen vragen op de\nzijlijn."}, {"type": "techniek", "title": "B. EEN-TWEE OF TECHNIEK; TEGENSTANDER NAAST JE", "content": "Techniek uitvoeren met een tegenstander naast je.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander naast je te passeren.\n- Een 1 : 2 aangaan om een tegenstander naast je voorbij te gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nnaast je.\nUit te voeren technieken:\n- Kappen achter het standbeen (Stap 4)\n- Kappen binnenkant voet (Stap 5)\n- Kappen buitenkant voet (Stap 5)\nA. Speler 1 speelt de bal op speler 2\nB. Speler 2 dribbelt de bal naar de middelste pylon en speler 3\nloopt hierbij mee.\nC. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 1 of hij passeert speler 3 met één van bovenstaande\ntechnieken.\nD. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nE. Speler 2 dribbelt over de achterlijn.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nVariatie\nVariatie 4: Het oefenen van de technieken Kappen binnenkant\nvoet (Stap 5), Kappen buitenkant voet (Stap 5) en Kappen achter\nstandbeen (Stap 4).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 3.\nSpeler 3 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1 en\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger (speler 3) mag het hele vak\ngebruiken om te verdedigen.\n- Speler 1 mag de bal alleen vragen op de\nzijlijn."}, {"type": "techniek", "title": "(6 : 4) OEFENING 2", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\n(Positiespel systeem Ajax)\nBij balverlies direct omschakelen. De middelste 4 nemen de\nposities over aan de zijkanten en het positiespel gaat gewoon\nverder.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 20m bij 15m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "RUIMTE VOETBAL 7 TEGEN 7", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen op een groot veld (ca. half voetbalveld).\nBeide teams verdedigen één kant van het veld, met daarop 2\ngrote poorten (min. 8 m. breed), die ca. 8 m. vanaf de achterlijn\nstaan.\nHet team in balbezit kan scoren door, zonder tussenkomst van de\ntegenstander, de bal naar elkaar over te spelen en daarna te\nscoren in één van de 2 poorten aan de lange zijde van de\ntegenstander..\nOpgelet:\n- men houdt balbezit na het score\n- er kan van beide kanten door de poorten worden gescoord.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "KRUIS- EN AANSLUITPAS OVER EEN LIJN", "content": "Is een oefening, waarbij de speler(s)de stappen van de\nonderstaande technieken, in zijwaartse richting, over een\nrechtlopende lijn uitvoeren.\nDe speler(s) moet(en) hierbij beide bewegingsvormen uit kunnen\nvoeren.\n1. Aansluitpas (Stap 1,2,3)\n2. Kruispas (Stap 1,2,3)\nOpgelet!\nDit is een aanleervorm. Met deze oefening leer je de speler(s) de\nbewegingsvormen van de stappen 1 t/m 3 van beide passen aan.\nMaterialen\nAantal spelers: gehele team.\nOrganisatie:\nDeze oefeningen kunnen op elke lijn van het\nvoetbalveld worden uitgevoerd (bijv. zijkant van\nhet 16-metergebied).\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst"}, {"type": "techniek", "title": "STAP 2.5 E: AANNEMEN-OPENEN, TOT 180º IN DIAMANTVORM (2)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet\nlangs speler 3 naar speler 2.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 3 speelt naar speler 4.\n- Idem als beschreven bij A, etc.\nD. Speler 4 speelt naar speler 5.\n- Idem als beschreven bij B, etc.\nE. Speler 5 speelt naar speler 6.\n- Idem als beschreven bij B, etc.\nF. Speler 6 speelt naar speler 4.\n- Idem als beschreven bij B, etc.\nG. Speler 4 speelt naar speler 6.\n- Idem als beschreven bij B, etc.\nH. Speler 6 dribbelt met de bal naar speler 7.\n- Speler 6 sluit achter speler 7 aan.\nI. Speler 7 start oefening op het moment dat de bal bij speler 5 is.\nVariatie in uitvoering:\n- Idem, andersom maar nu oefening met links uitvoeren.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nMaterialen\nAantal spelers: 7-12\nAantal ballen: 2-5\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet."}, {"type": "techniek", "title": "OEFENVORM 3", "content": "De spelers staan bij de aangegeven onderdelen opgesteld\nA. Speler 1 speelt de bal met de binnenkant van de rechtervoet op\nde naar rechts aanbiedende speler 2 en loopt daarna door richting\n2e paal om zich aan te bieden.\nB. Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet op de voorwaarts aanbiedende speler 3\nC. Intussen heeft speler 4 zich inzakkend aangeboden en kiest\ndaarbij het juiste moment van diepgaan om de bal in de loop\naangespeeld te krijgen van speler 3.\nD. De spelers 1 en 3 kiezen vervolgens het juiste moment om zich\nbij de eerste en tweede paal aan te bieden.\nE. Ook speler 5 kiest daarbij positie op de rand van het 16 meter\ngebied, om alsnog een doorgeschoten/afvallende bal af te werken.\nF. Intussen controleert speler 3 de bal en geeft hem voor op de,\nbij de eerste en tweede paal, ingelopen spelers 2 en 4.\nG. Daarna rond één van beiden de bal af op doel.\nVariatie in uitvoering:\nWisselen van kant; wisselen van kant is wisselen van speelbeen.\nMaterialen\nAantal spelers: alle\nAantal ballen: voldoende\nDoel: 1 (7.32m bij 2.44m)\nAantal pylonen: 4\nDoordraaien:\nMet de klok mee:\n- Speler 1 sluit achter in de rij van speler 3 aan\n- Speler 2 sluit achter in de rij van speler 1 aan.\n- Speler 3 sluit achter in de rij van speler 5 aan.\n- Speler 5 sluit achter in de rij van speler 2 aan.\n- Spelers 4 en 9 geven om beurten de voorzet.\nAanwijzingen\n- Bij het 1e paal lopen moet je zorgen voor de\nkeeper uit te komen, op het moment dat de\nvoorzet komt.Loop vooral NIET voorbij de 1e\npaal!\n- Bij het 2e paal lopen moet je zorgen om\nschuin achter de speler bij de 1e paal te\nkomen, om daar de bal op te kunnen pakken,\ndie achter deze speler, ter hoogte van de 2e\npaal, komt.\n- De 3e speler stelt zich schuin achter de\nspeler bij de 2e paal op, om een\ndoorgeschoten bal te kunnen verwerken.\n- Laat een voorzet van het doel afdraaien.\n- Speler in beweging, bal in beweging en de\nbal met een boodschap geven.\nNIET IN HET WATER 7 TEGEN 7\nMethodiek\nDeze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers, die\ntegen elkaar spelen.\nIn het veld staan 2 doelen met de achterkanten naar elkaar toe.\nTussen de doelen is een vak (water), waar geen spelers mogen\nkomen. De bal mg wel door het vak gespeeld worden.\nHet team dat scoort in het doel van de tegenstander krijgt 1 punt.\nOpgelet:\n- als een speler door het water loopt, krijgt de tegenstander een\nvrije bal op de achterlijn, aan de kant van het doel waar zij\nmoeten scoren.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 8\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb),
('O12', 29, '{"session_a": [{"type": "warming_up", "title": "NUMMER PASSSPEL", "content": "De spelers vormen een groepje van 5 spelers. Elke speler krijgt een nummer van\n1 t/m 5. De spelers lopen door elkaar in het vierkant en spelen elkaar\nnummergewijs ( 1 speelt naar 2; 2 speelt naar 3 etc.) de bal toe.\nOpgelet!\nGebruik het hele vak\nVariatie:\n- Laat de spelers kennis maken met verschillende afstanden.\n- Gebruik ook het andere been\nMaterialen\nTijd: 10-15 min\nPylonen: 4 pylonen om het speelveld uit te zetten\nBallen: voor een vijftal 1 bal\nSTAP 2.8 C: KAATSEN HOOG (MET BINNENKANT VOET) TOT 90º\nMethodiek\nA. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet in de handen van speler 3, etc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- Open draaien, naar de speelrichting.\n- De bal met de juiste snelheid/richting door\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "3. (6 : 3)", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 3\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 9\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "BELGISCH VOETBAL 6 TEGEN 6 + 2 KEEPERS", "content": "Deze oefenvorm wordt uitgevoerd met 2 teams van 6 spelers en 1\nkeeper, die tegen elkaar spelen.\nElk team verdedigt één doel. De doelen staan in het midden van\nhet veld met de achterkanten tegen elkaar.\nAls je scoort in het doel van de tegenstander krijg je een punt.\nVariatie:\n- als een team een goede hoge bal kan spelen, evt.toevoegen dat\nde bal niet hoog gepeeld mag worden, of omgekeerd als ze het\nniet kunnen.\nMaterialen\nAantal spelers: 12 + 2 Keepers\nAantal ballen: 5\nAantal pylonen: 4\nDoel: 2\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "warming_up", "title": "TENEN TIKKERTJE/HAKKEN TIKKERTJE", "content": "Bij deze tikvorm lopen alle spelers, tikker en overige spelers, op hun tenen over\nhet veld.\nEen variant hierop is het lopen op de hakken.\nMaterialen\nAantal spelers: 15\nOrganisatie:\nDe afmeting van het vak is 10 bij 15 meter."}, {"type": "techniek", "title": "STAP 2.6 E: KAATSEN-OPENEN, TOT 180º IN DIAMANTVORM (2)", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet\nlangs speler 3 naar speler 2.\nB. Speler 2 speelt naar speler 3.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 speelt naar speler 4.\n- Speler 5 biedt zich \"voorwaarts\" aan.\n- Speler 4 biedt zich \"naar links\" aan.\n- Speler 3 speelt de bal direct met de binnenkant van de\nrechtervoet langs speler 5 naar speler 4.\nD. Speler 4 speelt naar speler 5.\n- Idem als beschreven bij B, etc.\nE. Speler 5 speelt naar speler 6.\n- Speler 6 biedt zich \"naar links\" aan.\n- Speler 5 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 6.\nF. Speler 6 speelt naar speler 4.\n- Idem als beschreven bij B, etc.\nG. Speler 4 speelt naar speler 6.\n- Speler 6 biedt zich \"naar rechts\" aan.\n- Speler 4 kaatst de bal met de binnenkant van de rechtervoet\nterug.\n- Speler 6 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nH. Speler 6 dribbelt met de bal naar speler 7.\n- Speler 6 sluit achter speler 7 aan.\nI. Speler 7 start oefening op het moment dat de bal bij speler 5 is.\nVariatie in uitvoering:\nIdem, andersom maar nu oefening met links uitvoeren.\nMaterialen\nAantal spelers: 7-12\nAantal ballen: 2-5\nAantal pylonen: 6\nAfstand van pylonen:\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "VERDEDIGEN DOOR MIDDENVELDERS EN VERDEDIGERS (5+KEEPER : 6)", "content": "D.w.z. dat 6 aanvallers/ middenvelders d.m.v. samenspel moeten\nzien te scoren op het grote doel.\nDe 5 verdedigers/ middenvelders + keeper moeten daarbij d.m.v.\nsamenwerken zo goed mogelijk positioneel verdedigen.\nBal afgepakt dan kunnen de verdedigers scoren door de bal over\nde lijn van één van de doeltjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 11+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 30m bij 35m\nD-pupillen: 35m bij 40m\nC-,B-,A-junioren: 40m bij 45m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nVerdedigers/middenvelders bij verdedigen\ncoachen op:\n- het inzakken van de middenvelder en het\nuitverdedigen vanuit de zone naar de kant\nvan de bal\n- het knijpen en kantelen van de verdedigers,\ndaar waar nodig\n- het gebruik maken van de buitenspelval het\ncoachen van elkaar(het initiatief ligt bij de\nachterste speler)."}, {"type": "partijvorm", "title": "PARTIJVORM 6:6 + 2 KEEPERS", "content": "Zes aanvallers moeten d.m.v. samenspel/ individuele actie de 6\nverdedigers uitspelen,om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij opnieuw.\nMaterialen\nAantal spelers:12 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nF-pupillen: 35m bij 30m\nE-pupillen: 35m bij 30m\nD-pupillen: 40m bij 35m\nC-junioren: 45m bij 40m\nB-,A-junioren: 50m bij 45m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een diamantvorm\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}]}'::jsonb),
('O12', 30, '{"session_a": [{"type": "warming_up", "title": "TEGENSTANDER VOOR JE: IN EEN RECHTHOEKVORM (2)", "content": "De onderstaande stappen van de volgende technieken dienen\nnaar eigen inzicht, rekening houdend met de beschikbare tijd,\naangeleerd te worden.\nA. Speler 1 dribbelt richting middelste pylon\n- Speler 1 dribbelt de bal met de buitenkant van de rechtervoet,\ninzet beweging binnenkant rechter voet.\nB. Speler 1 voert één van de onderstaande bewegingen uit:\n- Aai buitenkant voet (Stap 5A)\n- Sleep (Stap 4A)\n- Uitstappen meenemen (Stap 5A)\n- Akka (binnen-voor) (Stap 3A)\n- Akka (binnen-buiten) (Stap 3A)\nC. Speler 1 speelt naar speler 2\n- Speler 1 speelt de bal met de binnenkant van de linkervoet.\n- Speler 2 neemt de bal met de binnenkant van de rechtervoet\naan.\nVariatie:\nEen dubbele schaarbeweging door 2x met de voet om de bal heen\nte bewegen.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen/ organisatievormen (men moet elke\ntechniek voldoende zien te beheersen).\nMaterialen\nAantal spelers: 3\nAantal ballen: 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de plaats in van speler 2. Speler\n2 voert vervolgens de oefening, met het andere\nbeen, in tegenovergestelde richting uit. Daarna\nneemt deze speler de plaats in van speler 2, enz.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.8 C: KAATSEN HOOG (MET BINNENKANT VOET) TOT 90º", "content": "A. Speler 1 speelt naar speler 2\n- Speler 2 biedt zich opengedraaid \"voorwaarts\" aan.\n- Speler 1 gooit de bal onderhands, op kniehoogte met een boog\nnaar speler 2.\nB. Speler 2 speelt naar speler 3\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet in de handen van speler 3, etc.\nVariatie in uitvoering:\nIdem, andersom met links.\nVariatie in aanbieden:\nNaar rechts\nNaar links\nAchterwaarts\nMaterialen\nAantal spelers: 3\nAantal pylonen: 3\nAantal ballen: 1\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 5 m\nDoordraaien:\nNaar eigen inzicht wisselen van functie (na 10 x).\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nKaatsen binnenkant voet:\n- Open draaien, naar de speelrichting.\n- De bal met de juiste snelheid/richting door\nspelen.\n- Laag zitten (goed door de knieën).\n- Knie omhoog brengen.\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten."}, {"type": "techniek", "title": "3. (5 : 2 + 3)", "content": "Vijf aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de 2 verdedigers de bal kunnen veroveren.\nWanneer de verdedigers de bal onderscheppen dan moeten zij de\nruimte zoeken met een lange pass naar het andere vak om\nzodoende het spel te verleggen.\nTevens gaan 2 verdedigers en 2 aanvallers mee naar het andere\nveld. Nu moeten de vijf verdedigers d.m.v. samenspel de bal in\nhun bezit zien te houden zonder dat de 2 aanvallers de bal\nkunnen veroveren. Etc.\nVariatie in aanbieding:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 6\nAfstand tussen de pylonen: 2x (15m bij 12m)\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- omschakeling van balbezit naar balverlies\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "techniek", "title": "KANTELEN VOETBAL 7 TEGEN 7", "content": "Deze oefening wordt uitgevoerd met 2 teams van elk 7 spelers,\nwaarbij van elk team 1 speler in één van de 2 vierkanten staat.\nHet team in balbezit kan scoren door hun speler in het vierkant\naan te spelen, die vervolgens de bal doorspeelt naar een 3e\nspeler van het team.\nNa elke score draaien de spelers door en komt er een andere\nspeler in het vierkant te staan.\nHet balbezittende team behoudt na een score balbezit, maar de\nbal moet wel eerst weer worden teruggespeeld naar de eigen\nhelft, voordat er opnieuw gescoord kan worden.\nVariatie:\n- in plaats van de derde speler aan te spelen, mag de speler in het\nvierkant zelf met de bal het vierkant uitlopen.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 22\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}], "session_b": [{"type": "test", "title": "WENDBAARHEIDSTEST 1", "content": "Voor deze test wordt in het strafschopgebied, tussen de doellijn\nen de rand van het gebied, een parcours ( zie tekening) uitgezet.\nHet protocol voor deze test luidt als volgt:\nDe test start vanuit buikligging. Vervolgens wordt het hele traject\nin korte sprintjes, van pylon naar pylon, afgelegd.\nDe pylonen worden daarbij,tot het bereiken van de finish, telkens\nzo kort mogelijk gerond.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen:8\nAfstand tussen de pylonen:gebruik de\naangegeven lijnen en verdeel de tussenliggende\nruimte gelijkmatig\nSchrijfbenodigdheden\nAanwijzingen\n- ontwikkel, zowel heen als terug, een zo\nhoog mogelijke snelheid\n- draai kort om de pylon\n- neem minimaal 2-3 minuten rust tussen\ntwee testen\nSPRINTTEST\nMethodiek\nVoor deze test wordt in de breedte van het strafschopgebied, op\neen onderlinge afstand van tekens 10 meter, met 5 pylonen een\nparcours uitgezet.\nDe spelers starten de sprint vanaf de zijkant van het “16-\nmetergebied” vanuit stilstand en sprinten vervolgens om de\neerste pylon heen weer terug, gevolgd door een sprint om de\ntweede pylon heen en weer terug. Idem om de derde en de vierde\npylon.\nDe behaalde eindtijd wordt gemeten en vastgelegd.\nMaterialen\nAantal spelers: alle spelers\nAantal pylonen: 5\nAfstand tussen de pylonen: 10 mtr.\n1 stopwatch\nSchrijfbenodigdheden.\n- deze test heeft tot doel om de “reactie/\nacceleratie- en/of de maximale snelheid” te\ntoetsen/meten.\nAanwijzingen\n- zowel heen als terug een zo hoog mogelijke\nsnelheid ontwikkelen\n- kort om de pylon draaien\n- neem minimaal 2-3 minuten rust tussen\ntwee testen."}, {"type": "techniek", "title": "LIJNDRIBBEL 4:3 MET DOEL", "content": "d.w.z. dat 4 aanvallers d.m.v. samenspel/ een persoonlijke actie 3\nverdedigers uitspelen, om daarna in het doel te scoren.\nOpgelet!\nDe 4 aanvallers mogen bij deze actie geen buitenspel lopen. De\nbuitenspellijn wordt hierbij bepaald door de verdediger (alleen van\ntoepassing voor teams 11-11).\nDe verdedigers kunnen de afgepakte bal scoren door de bal over\nde lijn aan de overzijde te dribbelen.\nMaterialen\nAantal spelers: 7\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen:\nF-pupillen: 20m bij 15m\nE-pupillen: 25m bij 20m\nD-pupillen: 30m bij 25m\nC-,B-,A-junioren: 35m bij 30m\nDoel: 3 bij 1 meter\nAanwijzingen\nAanvallers coachen op:\n- het samenspelen vanuit een ruit vorm,\nwaarbij gezorgd moet worden dat de\nnummer 3 de vrije man is\n- het creëren van een twee tegen een situatie\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers\nVerdedigers coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)."}]}'::jsonb),
('O12', 31, '{"session_a": [{"type": "warming_up", "title": "STAP 2.1 D: AANBIEDEN, TOT 135º IN Y-VORM", "content": "A. Speler 1 speelt naar speler 2.\n- speler 2 biedt zich \"voorwaarts\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"voorwaarts\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Spelers 3 dribbelt met de bal naar speler 8.\n- speler 3 wisselt van kant ensluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nOpgelet!\n- idem aan de andere kant voor de spelers 5 t/m 8, alleen dan met\nlinks uitvoeren.\nVariatie in uitvoering:\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\n- naar rechts\n- naar links\n- achterwaarts\nMaterialen\nAantal spelers: 8-14\nAantal ballen: 4\nAantal pylonen: 4\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- wisselen door in de andere rij aan te sluiten.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "STAP 2.6 E: KAATSEN-OPENEN, TOT 180º IN DIAMANTVORM (1) WREEFTRAP", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet\nlangs speler 3 naar speler 2.\nB. Speler 2 speelt naar speler 3.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 speelt naar speler 4.\n- Speler 5 biedt zich \"voorwaarts\" aan.\n- Speler 4 biedt zich \"naar links\" aan.\n- Speler 3 speelt de bal direct met de wreef van de rechtervoet\nlangs speler 5 naar speler 4.\nD. Speler 4 speelt naar speler 5.\n- Speler 5 biedt zich \"naar rechts\" aan.\n- Speler 4 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 5.\nE. Speler 5 speelt naar speler 6.\n- Speler 6 biedt zich \"naar links\" aan.\n- Speler 5 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 6.\nSpeler 6 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nF. Speler 6 dribbelt met de bal naar speler 7.\n- Speler 6 sluit achter speler 7 aan.\nG. Speler 7 start oefening op het moment dat de bal bij speler 5 is.\nVariatie in uitvoering:\nIdem, andersom maar nu oefening met links uitvoeren.\nMaterialen\nAantal spelers: 7-12\nAantal ballen: 2-5\nAantal pylonen: 6\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 20 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten.\nWreeftrap:\n- Strak inspelen met gevoel.\n- Spanning in de voet, enkel strekken en\nspannen.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- Bal in het hart raken."}, {"type": "techniek", "title": "(6 : 4) OEFENING 2", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\n(Positiespel systeem Ajax)\nBij balverlies direct omschakelen. De middelste 4 nemen de\nposities over aan de zijkanten en het positiespel gaat gewoon\nverder.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 10\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 20m bij 15m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 7:7", "content": "Zeven aanvallers moeten d.m.v. samenspel/ individuele actie 7\nverdedigers uitspelen, om daarna in één van de twee\ntegenoverstaande doeltjes te scoren.\nDe verdedigers kunnen de afgepakte bal scoren in één van de\ntwee andere doeltjes.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij\nopnieuw.opnieuw.\nMaterialen\nAantal spelers: 14\nAantal ballen: 5\nAantal pylonen: 12\nAfstand tussen pylonen:\nE-pupillen: 35m bij 40m\nD-pupillen: 40m bij 45m\nC-junioren: 45m bij 50m\nB-,A-junioren: 50m bij 55m\nDoel: 4 (2mtr.)\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een 3-1-3 formatie.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar (het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering."}], "session_b": [{"type": "warming_up", "title": "STOKKENLOOP (3)", "content": "Is een oefening, waarbij de voorwaartse en zijwaartse vormen\ngecombineerd worden en aangeleerd over de stokken. De\noefening is opgebouwd van grove motoriek naar de fijne motoriek.\nDat wil zeggen binnen de looptraining, er wordt gewerkt van een\nskipping naar skipping 45 graden en vervolgens naar kort\nvoetenwerk.\nEr moet hierbij wel nadrukkelijk worden gelet op het lichtvoetig\nagreren over de stokken. Dat wil zeggen dat alles met de bal van\nde voet wordt uitgevoerd. Ten allen tijden wordt er op de bal van\nde voet gelopen.\nStap 1: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt voorwaarts genomen en vervolgens wordt er met twee\nvoeten teruggestapt, de derde stok wordt zijwaarts genomen en\nde vijfde stok vervolgens weer voorwaarts. De tussen stokken\nworden gelopen met één voet tussen de stokken.\nStap 2: Er wordt met de linkervoet begonnen. De eerste stok\nwordt voorwaarts genomen en vervolgens wordt er met twee\nvoeten teruggestapt, de derde stok wordt zijwaarts genomen en\nde vijfde stok vervolgens weer voorwaarts. De tussen stokken\nworden gelopen met één voet tussen de stokken.\nStap 3: Er wordt met de linkervoet begonnen. De eerste stok\nwordt zijwaarts genomen en vervolgens wordt er met twee voeten\nteruggestapt, de derde stok wordt voorwaarts genomen en de\nvijfde stok vervolgens weer zijwaarts. De tussen stokken worden\ngelopen met één voet tussen de stokken.\nStap 4: Er wordt met de rechtervoet begonnen. De eerste stok\nwordt zijwaarts genomen en vervolgens wordt er met twee voeten\nteruggestapt, de derde stok wordt voorwaarts genomen en de\nvijfde stok vervolgens weer zijwaarts. De tussen stokken worden\ngelopen met één voet tussen de stokken.\nDifferentiatie:\nDe beweging wordt aan beide kanten uitgevoerd. Dat wil zeggen\ndat de zijwaarts rechts en links uitgevoerd moeten worden.\nLet op!\nDe romphouding moet ten allen tijden recht zijn en er moet een\narminzet aanwezig zijn.\nMaterialen\nAantal spelers: het gehele team.\nAantal stokkenparcours:\nEén, bij voorkeur twee.\nAantal pylonnen:\n12\nAantal stokken:\n5\nOrganisatie:\nEén situatie waarbij de groep achter de\nspeedladder staat, bij voorkeur twee situaties.\nAanwijzingen\nLet op!\nFrequentieaanpassing: Je lichaam moet\nboven je benen blijven alleen de snelheid van\nje voeten wordt aangepast."}, {"type": "techniek", "title": "STAP 2.3 E: INGOOIEN, AANNEMEN-OPENEN, TOT 180º IN LIJNVORM, WREEF", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 gooit de bal in.\n- Speler 2 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nB. Speler 2 speelt naar speler 1.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal met de binnenkant van de rechtervoet.\n- Speler 1 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nC. Speler 1 speelt naar speler 3.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 1 speelt de bal met de wreef van de rechtervoet.\n- Speler 3 pakt de bal op, etc.\nD. Speler 3 start oefening opnieuw\nVariatie in uitvoering:\n- Idem, andersom maar nu oefening met links uitvoeren.\n- Aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\n- Speler 2 en speler 3 bepalen zelf hoe ze zich aanbieden.\nMaterialen\nAantal spelers: 4\nAantal ballen: 1\nAantal pylonen: 3\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 20 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler. Speler 3 start met dezelfde\noefening maar dan aan de andere kant.\nAanwijzingen\nIngooi:\n- Beiden voeten houden contact met de\ngrond.\n- De bal achter het hoofd loslaten.\n- Beide handen op de bal houden.\n- Voeten in de richting van het gooien.\n- Op het juiste been ingooien.\nAanbieden:\n- Vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Strak inspelen met gevoel.\n- Doorzwaaien van het schietbeen.\n- Bal in het hart raken.\n- Spanning in de voet.\nWreeftrap:\n- Strak inspelen met gevoel.\n- Spanning in de voet, enkel strekken en\nspannen.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- Bal in het hart raken."}, {"type": "techniek", "title": "STAP 3: KOPDUEL 1 : 1 MET PASSIEVE/ACTIEVE WEERSTAND", "content": "Bij deze oefening staat er een verdediger voor speler 2.\nA. Speler 1 speelt naar speler 2\n- Speler 1 gooit de bal onderhands op de, naar links en rechts,\nbewegende speler 2. Deze probeert hiermee de verdediger te\nontwijken.\nB. Speler 2 speelt naar speler 1\n- Speler 2 kopt de bal, met een één/ tweebenige afzet, terug naar\nspeler 1.\nOpgelet!\nDe verdediger voert langzaam de weerstand (van passief naar\nactief) op.\nVariatie in uitvoering:\nTel aantal onderscheppingen.\nMaterialen\nAantal spelers: 3\nAantal ballen: 1-2\nAantal pylonen: 2\nOnderlinge afstand pylonen: 3-4 mtr.\nDoordraaien:\nWisselen van functie naar eigen inzicht.\nAanwijzingen\n- Vroegtijdig afzetten.\n- Afzetbeen terugbrengen in spanboog.\n- Zwaaibeen blijft gebogen voor-hoog.\n- Bal moet op het hoogste punt van de\nsprong worden gekopt (dode punt).\n- Juiste moment bovenlichaam naar voren en\narmen naar achter.\n- Bal raken met het voorhoofd.\n- De bal goed richting geven, door de\nduwbeweging in de richting van speler 1 te\nmaken.\nAANVALLEN DOOR MIDDENVELDERS EN AANVALLERS (6 : 5+KEEPER)\nMethodiek\nD.w.z. dat de 6 aanvallers/ middenvelder d.m.v. samenwerken\nkansen creëren.\nDe 5 verdedigers /middenvelders+ keeper kunnen hierbij scoren\ndoor de bal over de lijn van één van de kleine doetjes te dribbelen.\nDe aanvallers kunnen op het grote doel scoren.\nDe oefening start altijd bij de aanvallers.\nMaterialen\nAantal spelers: 11+keeper\nAantal ballen: 1\nAantal pylonen: 8\nAfstand tussen de pylonen:\nE-pupillen: 30m bij 35m\nD-pupillen: 35m bij 40m\nC-,B-,A-junioren: 40m bij 45m\nDoel: 7,32 en 2,44\nKleine doelen: 5-8 meter\nAanwijzingen\nMiddenvelders/aanvallers bij aanvallen\ncoachen op:\n- het samenspelen vanuit een halve kom\n- het opkomen van de middenvelder\n- het zo breed en diep mogelijk staan van de\ntwee buitenste spelers (7+11)\n- het loskomen van de tegenstander d.m.v.\nvooracties.\n- het creëren van een twee tegen een situatie.\nMiddenvelders/aanvallers bij balverlies\ncoachen op:\n- het knijpen, daar waar nodig\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het direct druk zetten op de bal."}]}'::jsonb),
('O12', 32, '{"session_a": [{"type": "warming_up", "title": "STAP 2.1 E: AANBIEDEN, TOT 180º IN LIJN/STROOMVORM", "content": "A. Speler 1 speelt naar spelers 2.\n- speler 2 biedt zich \"naar links\" aan\n- speler 1 speelt de bal met de binnenkant van de rechtervoet\n- speler 2 neemt de bal opengedraaid met de binnenkant van de\nlinkervoet aan.\nB. Speler 2 speelt naar speler 3.\n- speler 3 biedt zich \"naar links\" aan\n- speler 2 speelt de bal met de binnenkant van de rechtervoet\n- speler 3 neemt de bal opengedraaid met de binnenkant van de\nlinkervoet aan.\nC. Speler 3 dribbelt met de bal naar speler 8.\n- speler 3 sluit achter speler 8 aan.\nD. Speler 4 start oefening opnieuw\nE. Spelers 5, 6, 7 en 8\n- idem als beschreven bij A. B. C en D,etc.\nVariatie in uitvoering:\n- aannemen met links en spelen met rechts of aannemen met\nrechts en spelen met links.\nVariatie in aanbieden:\nNaar rechts\nAchterwaarts\nVoorwaarts\nMaterialen\nAantal spelers: 4-5\nAantal ballen: 1\nAantal pylonen: 9\nAfstand van pylonen:\n1e jaars E-pupillen: 10 m\n2e jaars E-pupillen: 12 m\nD-,C-,B-,A-junioren: 15 m\nDoordraaien:\n- achter de bal aan doorlopen naar de volgende\npylon.\nAanwijzingen\nAanbieden:\n- vragen om de bal, na de aanname van de\nspeler.\nAannemen:\n- bal moet voor je liggen, maar binnen bereik\n- snelheid houden na de aanname voor de\nvolgende actie\n- open aannemen, in de speelrichting.\nSpelen binnenkant voet:\n- de bal met de juiste snelheid en op het\ngoede been aanspelen\n- strak inspelen met gevoel\n- doorzwaaien van het schietbeen\n- bal in het hart raken\n- spanning in de voet."}, {"type": "techniek", "title": "EEN-TWEE OF TECHNIEK; TEGENSTANDER VANAF DE ZIJKANT", "content": "Techniek uitvoeren met een tegenstander vanaf de zijkant.\nVoer onderstaande oefeningen apart van elkaar uit:\n- Techniek uitvoeren om een tegenstander vanaf de zijkant te\npasseren.\n- Een 1 : 2 aangaan om een tegenstander vanaf de zijkant voorbij\nte gaan.\n- Een keuze maken om een 1 : 2 aan te gaan of om één van de\naangegeven technieken uit te voeren, met een tegenstander\nvanaf de zijkant.\nUit te voeren technieken:\n- 2x Kappen buitenkant voet (Stap 5)\n- Pirouette (Stap 7)\n- Aai kappen achter het standbeen(Stap 6)\n- De Schijntrap (Stap 6)\nA. Speler 1 speelt de bal op speler 2\nB. Speler 2 dribbelt de bal naar de middelste pylon en speler 3\nkomt vanaf de zijkant aanlopen.\nC. Speler 2 maakt een keuze: hij speelt de bal voor een 1 : 2 op\nspeler 1 of hij passeert speler 3 met één van bovenstaande\ntechnieken.\nD. Speler 2 dribbelt of loopt door om de bal te ontvangen.\nE. Speler 2 dribbelt over de achterlijn.\nOpgelet!\nHandel bovenstaande technieken naar eigen inzicht af en gebruik\nhiervoor meerdere lessen (men moet eerst elke techniek\nvoldoende zien te beheersen).\nMaterialen\nAantal spelers: 3\nAantal ballen; 1\nAantal pylonen: 6\nOnderlinge afstand pylonen: 10 mtr.\nDoordraaien:\nSpeler 1 neemt de taak over van speler 3.\nSpeler 3 neemt de taak over van speler 2.\nSpeler 2 neemt de taak over van speler 1 en\nstart nu de oefening.\nEtc.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst.\n- De verdediger (speler 3) mag het hele vak\ngebruiken om te verdedigen.\n- Speler 1 mag de bal alleen vragen op de\nachterlijn."}, {"type": "techniek", "title": "3. (6 : 3)", "content": "Zes aanvallers moeten d.m.v. samenspel de bal in hun bezit zien\nte houden zonder dat de verdedigers de bal kunnen veroveren.\nHierbij wordt gewerkt met 3 teams(3 kleuren hesjes) van elk 3\nspelers. Twee teams vormen de aanvallende partij en het derde\nteam is, totdat zij de bal hebben veroverd, de verdedigende partij.\nDirect na de verovering wisselt het verdedigende team van taak\nmet het aanvallende team die de fout veroorzaakt heeft.\nVariatie in uitvoering:\nde aanvallers mogen de bal maar 2x raken.\nMaterialen\nAantal spelers: 9\nAantal ballen: 1\nAantal pylonen: 4\nAfstand tussen de pylonen: 15m bij 12m\nAanwijzingen\nAanvallers coachen op:\n- het vrijlopen en aanspeelbaar zijn, zonder\nbal\n- het innemen van de positie, zodanig dat ze\nzicht houden op het hele veld\n- het altijd in beweging zijn van de bal en de\nspeler\n- het klein maken van het veld bij balverlies\nen het zo groot mogelijk maken van het veld\nbij balbezit\n- het geven van de bal met een boodschap\n(in de ruimte en op welk been)\n- het vragen om de bal\n- het nacoachen van de bal/ pass\n- het zodanig innemen van een positie, dat er\naltijd driehoeken worden gevormd (altijd met\neen middelste man)\n- het zodanig innemen van een positie door\nde middelste speler, dat hij altijd direct of\nindirect (2x raken) door kan spelen\nVerdediger coachen op:\n- het rekening houden met een goed zicht op\nde posities van de aanvallers\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het coachen van elkaar bij het verdedigen\n(het initiatief ligt bij de achterste speler)"}, {"type": "partijvorm", "title": "PARTIJVORM 7:7 + 2 KEEPERS", "content": "Zeven aanvallers moeten d.m.v. samenspel/ individuele actie 7\nverdedigers uitspelen, om daarna in het tegenoverstaande doel te\nscoren.\nDe verdedigers kunnen de afgepakte bal scoren door hetzelfde\naan de andere kant van het vak te doen.\nOpgelet!\n- bal buiten het veld, dan start het andere team de partij\nopnieuw.opnieuw.\nMaterialen\nAantal spelers:14 +2 keepers\nAantal ballen: 5\nAantal pylonen: 4\nAfstand tussen pylonen:\nE-pupillen: 40m bij 35m\nD-pupillen: 45m bij 40m\nC-junioren: 50m bij 45m\nB-,A-junioren: 55m bij 50m\nDoel: 2\nF- en E-pupillen: 5m bij 2m\nD-,C-,B-,A-junioren: 7.32m bij 2.44\nAanwijzingen\nBij de aanval coachen op:\n- het samenspelen vanuit een 1-3-1-3\nformatie.\n- het uiteen bewegen bij balbezit\n- het voorkomen van buitenspel\n- het maken van keuzes ( 1:1 of overspelen)\naan de bal\n- het rekening houden met omschakeling bij\nbalverlies en ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het knijpen, daar waar nodig\n- het gebruik maken van de buitenspelregel\n- het coachen van elkaar ( het initiatief ligt bij\nde achterste speler)\n- het rekening houden met omschakeling bij\nbalverovering.\nKeepers coachen op:\n- het altijd aanspeelbaar zijn bij balbezit\n- het coachen van je medespelers bij het\nverdedigen.\nOpmerkingen:\n- bij een partij op scherp mag men de bal vrij\nraken\n- leg accenten op: de individuele actie, het\nscoren onder druk, een snelle omschakeling,\nde conditionele (anaeroob- lactisch)/ mentale\nfactoren\n- houdt in de organisatie ook aandacht voor:\ngenoeg ballen om het veld, een strakke felle\ncoaching."}], "session_b": [{"type": "warming_up", "title": "BALGOOCHELAAR", "content": "Oefeningen, waarbij de spelers de stappen van de onderstaande\ntechnieken, op de plaats/ in voorwaartse richting moeten\nuitvoeren. De speler heeft daarbij een bal in de handen die hij, op\neen teken van de trainer, in verschillende standen langs zijn\nlichaam moet brengen..\n1. Tripling (Stap 1, 2, 3 en 4)\n2. Skipping ( Stap 1, 2, 3 en 4)\n3. Hielaanslag (Stap 1 en 2)\nOpgelet!\nDeze oefening kan ook uitgevoerd worden als aanleervorm.\nDoor de bal in verschillende posities te houden wordt er veel\ngevraagd van de rompstabiliteit van de speler. (Rompstabiliteit:\nhet stilhouden van het bovenlichaam.)\nMaterialen\nAantal spelers: 15\nAantal pylonen: 0\nAantal ballen: 15\nOrganisatie:\nDe spelers staan kris kras door elkaar in het 16-\nmeter gebied.\nAanwijzingen\n- Voor de beschrijving van de techniek zie\ntechnieklijst."}, {"type": "techniek", "title": "STAP 2.6 E: KAATSEN-OPENEN, TOT 180º IN DIAMANTVORM (2) WREEFTRAP", "content": "A. Speler 1 speelt naar speler 2.\n- Speler 3 biedt zich \"voorwaarts\" aan.\n- Speler 2 biedt zich \"naar rechts\" aan.\n- Speler 1 speelt de bal met de binnenkant van de rechtervoet\nlangs speler 3 naar speler 2.\nB. Speler 2 speelt naar speler 3.\n- Speler 1 biedt zich \"naar rechts\" aan.\n- Speler 2 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 3.\nC. Speler 3 speelt naar speler 4.\n- Speler 5 biedt zich \"voorwaarts\" aan.\n- Speler 4 biedt zich \"naar links\" aan.\n- Speler 3 speelt de bal direct met de wreef van de rechtervoet\nlangs speler 5 naar speler 4.\nD. Speler 4 speelt naar speler 5.\n- Idem als beschreven bij B, etc.\nE. Speler 5 speelt naar speler 6.\n- Speler 6 biedt zich \"naar links\" aan.\n- Speler 5 speelt de bal direct met de binnenkant van de\nrechtervoet naar speler 6.\nF. Speler 6 speelt naar speler 4.\n- Idem als beschreven bij B, etc.\nG. Speler 4 speelt naar speler 6.\n- Speler 6 biedt zich \"naar rechts\" aan.\n- Speler 4 kaatst de bal met de binnenkant van de rechtervoet\nterug.\n- Speler 6 neemt de bal opengedraaid met de binnenkant van de\nrechtervoet aan.\nH. Speler 6 dribbelt met de bal naar speler 7.\n- Speler 6 sluit achter speler 7 aan.\nI. Speler 7 start oefening op het moment dat de bal bij speler 5 is.\nVariatie in uitvoering:\nIdem, andersom maar nu oefening met links uitvoeren.\nMaterialen\nAantal spelers: 7-12\nAantal ballen: 2-5\nAantal pylonen: 6\nAfstand van pylonen:\nD-,C-,B-,A-junioren: 20 m\nDoordraaien:\nNa het spelen loopt elke speler door naar de\nvolgende pylon en neemt de positie in van de\nvorige speler.\nAanwijzingen\nAanbieden:\n- Voor de kaats vragen om de bal.\nAannemen:\n- Bal moet voor je liggen, maar binnen bereik.\n- Snelheid houden na de aanname voor de\nvolgende actie.\n- Open aannemen, in de speelrichting.\nKaatsen binnenkant voet:\n- De bal met de juiste snelheid en op het\ngoede been aanspelen.\n- Laag zitten (goed door de knieën).\n- Standbeen naast de bal.\n- Lichaam over de bal.\n- Bal tegen de schoen van het schietbeen\nlaten stuiten.\nWreeftrap:\n- Strak inspelen met gevoel.\n- Spanning in de voet, enkel strekken en\nspannen.\n- Standbeen iets voorbij de bal, bal blijft laag.\n- Standbeen iets achter de bal, bal aan de\nonderkant raken, bal gaat omhoog.\n- Bal in het hart raken."}, {"type": "techniek", "title": "OEFENVORM 4", "content": "De spelers staan bij de aangegeven onderdelen opgesteld\nA. Speler 1 speelt de bal op de aanbiedende speler 2.\nB. Speler 2 speelt de bal met de binnenkant van de rechtervoet\nterug op de aanbiedende speler 1.\nC. Speler 1 speelt vervolgens de bal op de aanbiedende speler 4.\nD. Speler 4 speelt, op zijn beurt, de bal direct door op de\ninlopende speler 3 en biedt zich daarna gelijk in de diepte weer\naan.\nE. Speler 3 speelt de bal naar de diepgaande speler 4.\nF. Speler 4 controleert de bal.\nG. Speler 4 geeft de bal voor op de intussen bij de eerste en\ntweede paal ingelopen spelers 1 en 2. Eén van beiden rond de bal\naf op doel.\nVariatie in uitvoering:\nWisselen van kant; wisselen van kant is wisselen van speelbeen.\nMaterialen\nAantal spelers: alle\nAantal ballen: 1\nDoel: 1 (7.32m bij 2.44m)\nAantal pylonen: 6\nDoordraaien:\nMet de klok mee:\n- Speler 1 sluit achter in de rij van speler 2 aan\n- Speler 2 sluit achter in de rij van speler 3 aan.\n- Speler 3 sluit achter in de rij van speler 1 aan.\n- Spelers 4 en 8 geven om beurten de voorzet.\nAanwijzingen\n- Bij het 1e paal lopen moet je zorgen voor de\nkeeper uit te komen, op het moment dat de\nvoorzet komt Loop vooral NIET voorbij de 1e\npaal!\n- Bij het 2e paal lopen moet je zorgen om\nschuin achter de speler bij de 1e paal te\nkomen om de bal die mogelijk achter deze\nspeler komt, ter hoogte van de 2e paal, te\nkunnen pakken.\n- Laat een voorzet van het doel afdraaien.\n- Speler in beweging, bal in beweging en de\nbal met een boodschap geven.\nBELGISCH VOETBAL 7 TEGEN 7 + 2 KEEPERS\nMethodiek\nDeze oefenvorm wordt uitgevoerd met 2 teams van 7 spelers en 1\nkeeper, die tegen elkaar spelen.\nElk team verdedigt één doel. De doelen staan in het midden van\nhet veld met de achterkanten tegen elkaar.\nAls je scoort in het doel van de tegenstander krijg je een punt.\nVariatie:\n- als een team een goede hoge bal kan spelen, evt.toevoegen dat\nde bal niet hoog gepeeld mag worden, of omgekeerd als ze het\nniet kunnen.\nMaterialen\nAantal spelers: 14 + 2 Keepers\nAantal ballen: 5\nAantal pylonen: 4\nDoel: 2\nAanwijzingen\nBij de aanval coachen op:\n- het maken van keuzes aan de bal( 1:1 of\noverspelen)\n- het rekening houden bij balverlies met\nomschakeling, ook bij het innemen van een\naanvallende positie.\nBij het verdedigen coachen op:\n- het rekening houden met een goed zicht op\nbeide aanvallers bij het innemen van een\nverdedigende positie\n- het isoleren van de aanvaller in balbezit\nnaar de zijkant van het veld\n- het rekening houden bij balverovering met\nomschakeling.\n- het aanzetten tot het maken van\npasseeracties. Pas als dit goed gaat kijk je of\nde juiste keuzes gemaakt worden\n(passeeractie of overspelen)"}]}'::jsonb)
